/** 一次性把 lv-ui 样式注入 document（幂等；与 lv-ui-prefs 同模式） */
export function ensureLvUiStyles(): void {
    try {
        if (typeof document === "undefined") return;
        if (document.getElementById("lv-ui-styles")) return;
        const style = document.createElement("style");
        style.id = "lv-ui-styles";
        style.textContent = LV_UI_CSS;
        (document.head || document.documentElement).appendChild(style);
    } catch {
        // ignore
    }
}

// 模块导入即注入：Svelte 仓与 Webpack 仓统一零接线生效
if (typeof document !== "undefined") {
    ensureLvUiStyles();
}

/* ========================================================================= */
/* 11. 零依赖 DOM 工厂（服务 Webpack/TS 仓；Svelte 仓直接用 CSS 类）           */
/* ========================================================================= */

type LvUiChild = Node | string | null | undefined | false;

function lvxH<K extends keyof HTMLElementTagNameMap>(
    tag: K,
    props?: Record<string, unknown> | null,
    ...children: Array<LvUiChild | Array<LvUiChild>>
): HTMLElementTagNameMap[K] {
    const el = document.createElement(tag);
    if (props) {
        for (const [key, value] of Object.entries(props)) {
            if (value === undefined || value === null || value === false) continue;
            if (key === "class") el.className = String(value);
            else if (key === "text") el.textContent = String(value);
            else if (key === "html") el.innerHTML = String(value);
            else if (key === "value") { (el as any).value = String(value); el.setAttribute("value", String(value)); }
            else if (key === "style" && typeof value === "object") Object.assign(el.style, value as Record<string, string>);
            else if (key === "dataset" && typeof value === "object") Object.assign(el.dataset, value as Record<string, string>);
            else if (key === "tabIndex") el.tabIndex = Number(value);
            else if (key === "maxLength") el.setAttribute("maxlength", String(Number(value)));
            else if (key === "ariaValueNow") el.setAttribute("aria-valuenow", String(value));
            else if (key === "ariaValueMin") el.setAttribute("aria-valuemin", String(value));
            else if (key === "ariaValueMax") el.setAttribute("aria-valuemax", String(value));
            else if (key.startsWith("on") && typeof value === "function") el.addEventListener(key.slice(2).toLowerCase(), value as EventListener);
            else if (value === true) el.setAttribute(key.replace(/[A-Z]/g, m => `-${m.toLowerCase()}`), "");
            else el.setAttribute(key.replace(/[A-Z]/g, m => `-${m.toLowerCase()}`), String(value));
        }
    }
    for (const child of children.flat()) {
        if (child === null || child === undefined || child === false) continue;
        el.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
    }
    return el;
}

/**
 * 历史变量别名桥接表（Legacy Token Bridge）
 * 为任意挂载了 data-lv-ui 的容器无感重定向 8 仓旧主色与背景变量，
 * 使旧页面即使未改动任何业务代码，只要挂上罩子即可一键继承 DL2 的品牌色调。
 */
export function applyLegacyTokenBridge(el: HTMLElement): void {
    if (!el || !el.style || typeof el.style.setProperty !== "function") return;
    const aliases: Record<string, string> = {
        // 小驴管家 (siyuan-home)
        "--home-primary": "var(--lvx-brand)",
        "--home-bg": "var(--lvx-canvas)",
        "--home-card-bg": "var(--lvx-surface)",
        "--home-text": "var(--lvx-text)",
        "--home-muted": "var(--lvx-text-muted)",
        "--home-border": "var(--lvx-border)",
        // 小驴人脉 (siyuan-contacts)
        "--contacts-primary": "var(--lvx-brand)",
        "--contacts-orange": "var(--lvx-energy)",
        "--contacts-surface": "var(--lvx-surface)",
        "--contacts-text": "var(--lvx-text)",
        // 小驴常用 (xiaolv-common)
        "--common-primary": "var(--lvx-brand)",
        "--common-surface": "var(--lvx-surface)",
        "--common-bg": "var(--lvx-canvas)",
        // 小驴拾遗 (siyuan-glean)
        "--glean-primary": "var(--lvx-brand)",
        "--glean-teal": "var(--lvx-brand)",
        "--glean-surface": "var(--lvx-surface)",
        // 小驴闪卡 (siyuan-lv-cards)
        "--riff-primary": "var(--lvx-brand)",
        "--card-surface": "var(--lvx-surface)",
        // 小驴考试 (siyuan-exam)
        "--exam-primary": "var(--lvx-brand)",
        "--exam-surface": "var(--lvx-surface)",
        // 小驴打卡 (siyuan-checkin)
        "--checkin-primary": "var(--lvx-brand)",
        // 小驴雷切 (siyuan-speed-switch)
        "--switch-primary": "var(--lvx-brand)",
    };
    for (const [key, val] of Object.entries(aliases)) {
        el.style.setProperty(key, val);
    }
}

/** 把任意元素升级为 lv-ui 根（挂 token + b3 隔离罩 + 历史变量桥接；主题/偏好属性由 lv-theme/lv-ui-prefs 写入） */
export function setupLvUiRoot<T extends HTMLElement>(el: T): T {
    try {
        el.setAttribute("data-lv-ui", "1");
        applyLegacyTokenBridge(el);
    } catch {
        // ignore
    }
    return el;
}

/**
 * 宿主表面脚手架 1：侧边 Dock 面板容器
 */
export function mountLvDockSurface(opts: {
    container: HTMLElement;
    padding?: string;
}): { unmount: () => void } {
    const el = opts.container;
    setupLvUiRoot(el);
    el.setAttribute("data-lv-surface", "dock");
    el.style.width = "100%";
    el.style.maxWidth = "100%";
    el.style.boxSizing = "border-box";
    el.style.overflowX = "hidden";
    el.style.overflowY = "auto";
    if (opts.padding) el.style.padding = opts.padding;

    return {
        unmount: () => {
            el.removeAttribute("data-lv-surface");
        },
    };
}

/**
 * 宿主表面脚手架 2：主工作区独占 Tab 页面容器
 */
export function mountLvTabSurface(opts: {
    container: HTMLElement;
    padding?: string;
}): { unmount: () => void } {
    const el = opts.container;
    setupLvUiRoot(el);
    el.setAttribute("data-lv-surface", "tab");
    el.style.width = "100%";
    el.style.height = "100%";
    el.style.boxSizing = "border-box";
    el.style.overflowY = "auto";
    el.style.background = "var(--lvx-canvas)";
    el.style.color = "var(--lvx-text)";
    if (opts.padding) el.style.padding = opts.padding;

    return {
        unmount: () => {
            el.removeAttribute("data-lv-surface");
        },
    };
}

/**
 * 宿主表面脚手架 3：顶栏/悬浮 Popover 气泡容器
 */
export function mountLvPopoverSurface(opts: {
    container: HTMLElement;
    maxWidth?: string;
}): { unmount: () => void } {
    const el = opts.container;
    setupLvUiRoot(el);
    el.setAttribute("data-lv-surface", "popover");
    el.style.background = "color-mix(in srgb, var(--lvx-surface) 86%, transparent)";
    el.style.backdropFilter = "blur(16px) saturate(180%)";
    (el.style as any).WebkitBackdropFilter = "blur(16px) saturate(180%)";
    el.style.border = "1px solid var(--lvx-border-strong)";
    el.style.borderRadius = "var(--lvx-r-lg)";
    el.style.boxShadow = "var(--lvx-inner-sheen), var(--lvx-shadow-3)";
    el.style.boxSizing = "border-box";
    if (opts.maxWidth) el.style.maxWidth = opts.maxWidth;

    return {
        unmount: () => {
            el.removeAttribute("data-lv-surface");
        },
    };
}

/**
 * 宿主表面脚手架 4：移动端/抽屉 Drawer 容器
 */
export function mountLvDrawerSurface(opts: {
    container: HTMLElement;
    side?: "left" | "right" | "bottom";
}): { unmount: () => void } {
    const el = opts.container;
    setupLvUiRoot(el);
    el.setAttribute("data-lv-surface", "drawer");
    el.style.background = "var(--lvx-surface-elevated)";
    el.style.boxShadow = "var(--lvx-inner-sheen), var(--lvx-shadow-3)";
    el.style.boxSizing = "border-box";
    const side = opts.side || "bottom";
    if (side === "bottom") {
        el.style.borderTopLeftRadius = "var(--lvx-r-hero)";
        el.style.borderTopRightRadius = "var(--lvx-r-hero)";
        el.style.borderTop = "1px solid var(--lvx-border-strong)";
        el.style.paddingBottom = "calc(16px + env(safe-area-inset-bottom, 0px))";
    }

    return {
        unmount: () => {
            el.removeAttribute("data-lv-surface");
        },
    };
}

function setupOverlayDismiss(
    container: HTMLElement,
    onClose: () => void,
    ignoreElements: Array<HTMLElement | null | undefined> = []
): { open: () => void; close: () => void } {
    let isOpen = false;
    const doc = container.ownerDocument || (typeof document !== "undefined" ? document : null);

    const onPointerDown = (ev: Event) => {
        if (!isOpen) return;
        const target = (ev as any).target as Node | null;
        if (!target) return;
        if (container.contains(target)) return;
        for (const el of ignoreElements) {
            if (el && el.contains(target)) return;
        }
        close();
    };

    const onKeyDown = (ev: Event) => {
        if (!isOpen) return;
        if ((ev as any).key === "Escape") {
            ev.preventDefault();
            ev.stopPropagation();
            close();
        }
    };

    const open = () => {
        if (isOpen) return;
        isOpen = true;
        container.setAttribute("data-open", "true");
        if (doc && typeof (doc as any).addEventListener === "function") {
            (doc as any).addEventListener("pointerdown", onPointerDown, true);
            (doc as any).addEventListener("keydown", onKeyDown, true);
        }
    };

    const close = () => {
        if (!isOpen) return;
        isOpen = false;
        container.setAttribute("data-open", "false");
        if (doc && typeof (doc as any).removeEventListener === "function") {
            (doc as any).removeEventListener("pointerdown", onPointerDown, true);
            (doc as any).removeEventListener("keydown", onKeyDown, true);
        }
        onClose();
    };

    return { open, close };
}

function splitNumAndUnit(val: string | number, explicitUnit?: string): { num: string; unit: string } {
    if (explicitUnit !== undefined) return { num: String(val), unit: explicitUnit };
    const str = String(val).trim();
    const match = str.match(/^([+-]?[\d,.]+)\s*(.*)$/);
    if (match && match[2]) return { num: match[1] || "", unit: match[2] || "" };
    return { num: str, unit: "" };
}

export interface LvxButtonOptions {
    label?: string;
    icon?: string;
    /** 右侧内嵌快捷键帽（Linear / Raycast 风格，如 "⌘S" / "Alt+1"） */
    kbd?: string;
    variant?: "default" | "primary" | "energy" | "ghost" | "danger";
    /** 左对齐行变体（设置行/列表行；默认居中对齐） */
    row?: boolean;
    /** 100% 宽度居中块级按钮 */
    block?: boolean;
    sm?: boolean;
    lg?: boolean;
    loading?: boolean;
    disabled?: boolean;
    ariaLabel?: string;
    type?: "button" | "submit";
    onClick?: (ev: MouseEvent) => void;
}

export function lvxButton(opts: LvxButtonOptions): HTMLButtonElement {
    const variant = opts.variant && opts.variant !== "default" ? ` lvx-btn--${opts.variant}` : "";
    const cls = `lvx-btn${variant}${opts.row ? " lvx-btn--row" : ""}${opts.block ? " lvx-btn--block" : ""}${opts.sm ? " lvx-btn--sm" : ""}${opts.lg ? " lvx-btn--lg" : ""}`;
    if (!opts.icon && !opts.loading && !opts.kbd) {
        return lvxH("button", {
            type: opts.type || "button",
            class: cls,
            text: opts.label,
            disabled: opts.disabled,
            ariaLabel: opts.ariaLabel,
            onclick: opts.onClick,
        });
    }
    const btn = lvxH("button", {
        type: opts.type || "button",
        class: cls,
        disabled: opts.disabled || opts.loading,
        "aria-busy": opts.loading ? "true" : undefined,
        ariaLabel: opts.ariaLabel || opts.label,
        onclick: opts.onClick,
    });
    if (opts.loading) btn.appendChild(lvxH("span", { class: "lvx-btn__spinner", "aria-hidden": "true" }));
    else if (opts.icon) btn.appendChild(lvxH("span", { class: "lvx-btn__icon", html: opts.icon, "aria-hidden": "true" }));
    if (opts.label) btn.appendChild(lvxH("span", { text: opts.label }));
    if (opts.kbd) btn.appendChild(lvxKbd(opts.kbd));
    return btn;
}

export function lvxIconButton(opts: {
    icon: string;
    label: string;
    variant?: "default" | "ghost" | "surface" | "primary" | "energy" | "danger";
    sm?: boolean;
    lg?: boolean;
    active?: boolean;
    disabled?: boolean;
    onClick?: (ev: MouseEvent) => void;
}): HTMLButtonElement {
    const v = opts.variant && opts.variant !== "default" ? ` lvx-iconbtn--${opts.variant}` : "";
    const sz = opts.sm ? " lvx-iconbtn--sm" : opts.lg ? " lvx-iconbtn--lg" : "";
    const btn = lvxH("button", {
        type: "button",
        class: `lvx-iconbtn${v}${sz}`,
        ariaLabel: opts.label,
        "aria-pressed": opts.active !== undefined ? (opts.active ? "true" : "false") : undefined,
        disabled: opts.disabled,
        onclick: opts.onClick,
    });
    btn.innerHTML = opts.icon;
    return btn;
}

export type LvxTone = "brand" | "neutral" | "energy" | "success" | "warn" | "danger";

export function lvxChip(opts: {
    text: string;
    tone?: LvxTone;
    size?: "sm" | "md" | "lg";
    icon?: string;
    closable?: boolean;
    interactive?: boolean;
    onClose?: () => void;
    onClick?: () => void;
}): HTMLSpanElement {
    const toneCls = opts.tone && opts.tone !== "brand" ? ` lvx-chip--${opts.tone}` : "";
    const szCls = opts.size && opts.size !== "md" ? ` lvx-chip--${opts.size}` : "";
    const interCls = opts.interactive || opts.onClick ? " lvx-chip--interactive" : "";
    const pressProps = opts.onClick ? {
        role: "button",
        tabIndex: 0,
        onkeydown: (ev: KeyboardEvent) => {
            if (ev.target !== ev.currentTarget) return;
            if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); (ev.currentTarget as HTMLElement).click?.(); }
        },
    } : {};
    if (!opts.icon && !opts.closable) {
        return lvxH("span", { class: `lvx-chip${toneCls}${szCls}${interCls}`, text: opts.text, onclick: opts.onClick, ...pressProps });
    }
    const chip = lvxH("span", { class: `lvx-chip${toneCls}${szCls}${interCls}`, onclick: opts.onClick, ...pressProps });
    if (opts.icon) chip.appendChild(lvxH("span", { text: opts.icon, "aria-hidden": "true" }));
    chip.appendChild(lvxH("span", { text: opts.text }));
    if (opts.closable) {
        const closeBtn = lvxH("button", {
            type: "button",
            class: "lvx-chip__close",
            text: "✕",
            ariaLabel: `移除 ${opts.text}`,
            onclick: (ev: Event) => {
                ev.stopPropagation?.();
                opts.onClose?.();
            },
        });
        chip.appendChild(closeBtn);
    }
    return chip;
}

export function lvxTag(opts: string | { text: string; tone?: LvxTone; size?: "sm" | "md" | "lg" }): HTMLSpanElement {
    if (typeof opts === "string") return lvxH("span", { class: "lvx-tag", text: opts });
    const toneCls = opts.tone && opts.tone !== "neutral" ? ` lvx-tag--${opts.tone}` : "";
    const szCls = opts.size && opts.size !== "md" ? ` lvx-tag--${opts.size}` : "";
    return lvxH("span", { class: `lvx-tag${toneCls}${szCls}`, text: opts.text });
}

export function lvxBadge(opts: { text?: string; tone?: LvxTone; dot?: boolean }): HTMLSpanElement {
    const toneCls = opts.tone && opts.tone !== "brand" ? ` lvx-badge--${opts.tone}` : "";
    const dotCls = opts.dot ? " lvx-badge--dot" : "";
    return lvxH("span", { class: `lvx-badge${toneCls}${dotCls}`, text: opts.dot ? "" : (opts.text || "") });
}

export function lvxAvatar(opts: {
    src?: string;
    text?: string;
    size?: "sm" | "md" | "lg";
    tone?: "brand" | "energy" | "success";
    status?: "online" | "busy" | "away" | "offline";
}): HTMLSpanElement {
    const size = opts.size && opts.size !== "md" ? ` lvx-avatar--${opts.size}` : "";
    const tone = opts.tone && opts.tone !== "brand" ? ` lvx-avatar--${opts.tone}` : "";
    const el = lvxH("span", { class: `lvx-avatar${size}${tone}` });
    if (opts.src) {
        const img = lvxH("img", { src: opts.src, alt: opts.text || "" });
        el.appendChild(img);
    } else {
        el.textContent = opts.text || "";
    }
    if (opts.status) {
        const stCls = opts.status !== "online" ? ` lvx-avatar__status--${opts.status}` : "";
        el.appendChild(lvxH("span", { class: `lvx-avatar__status${stCls}`, ariaLabel: opts.status }));
    }
    return el;
}

export function lvxCard(opts: { children?: Array<LvUiChild | Array<LvUiChild>>; hero?: boolean; flat?: boolean; interactive?: boolean; onClick?: (ev: MouseEvent) => void }): HTMLDivElement {
    const mods = `${opts.hero ? " lvx-card--hero" : opts.flat ? " lvx-card--flat" : ""}${opts.interactive ? " lvx-card--interactive" : ""}`;
    const pressProps = opts.interactive && opts.onClick ? {
        role: "button",
        tabIndex: 0,
        onkeydown: (ev: KeyboardEvent) => {
            if (ev.target !== ev.currentTarget) return;
            if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); (ev.currentTarget as HTMLElement).click?.(); }
        },
    } : {};
    return lvxH("div", { class: `lvx-card${mods}`, onclick: opts.onClick ? (ev: MouseEvent) => { const t = ev.target as HTMLElement | null; if (t?.closest?.("button,a,input,select,textarea")) return; opts.onClick?.(ev); } : undefined, ...pressProps }, ...opts.children || []);
}

/** 大数字主角块（40-48px/750 + 小标签灰阶在上层语义）；每屏 hero 深卡至多一块 */
export function lvxHeroNum(opts: { value: string | number; unit?: string; label?: string; tone?: "brand" | "energy" }): HTMLDivElement {
    const { num, unit } = splitNumAndUnit(opts.value, opts.unit);
    const valEl = lvxH("div", { class: `lvx-herton${opts.tone ? ` lvx-herton--${opts.tone}` : ""}`, text: num },
        unit ? lvxH("span", { class: "lvx-herton__unit", text: unit }) : null,
    );
    return lvxH("div", { class: "lvx-hero" },
        opts.label ? lvxH("span", { class: "lvx-herton-label", text: opts.label }) : null,
        valEl,
    );
}

export function lvxSwitch(opts: { checked?: boolean; disabled?: boolean; sm?: boolean; lg?: boolean; label?: string; ariaLabel: string; onChange?: (checked: boolean) => void }): HTMLLabelElement {
    const input = lvxH("input", { type: "checkbox", "aria-label": opts.ariaLabel }) as HTMLInputElement;
    input.checked = !!opts.checked;
    input.disabled = !!opts.disabled;
    if (opts.onChange) input.addEventListener("change", () => opts.onChange!(input.checked));
    const sz = opts.sm ? " lvx-switch--sm" : opts.lg ? " lvx-switch--lg" : "";
    const wrap = lvxH("span", { class: `lvx-switch${sz}${opts.disabled ? " is-disabled" : ""}` },
        input,
        lvxH("span", { class: "lvx-switch__track" }),
        lvxH("span", { class: "lvx-switch__knob" }),
    );
    return lvxH("label", { class: "lvx-field-switch" }, wrap, opts.label ? lvxH("span", { text: opts.label }) : null);
}

export function lvxCheckbox(opts: { checked?: boolean; indeterminate?: boolean; label?: string; disabled?: boolean; onChange?: (checked: boolean) => void }): HTMLLabelElement {
    const input = lvxH("input", { type: "checkbox" }) as HTMLInputElement;
    input.checked = !!opts.checked;
    input.disabled = !!opts.disabled;
    if (opts.indeterminate) (input as any).indeterminate = true;
    const checkWrap = lvxH("span", {
        class: "lvx-check",
        "data-indeterminate": opts.indeterminate ? "true" : undefined,
    }, input, lvxH("span", { class: "lvx-check__box" }));
    input.addEventListener("change", () => {
        checkWrap.setAttribute("data-indeterminate", "false");
        opts.onChange?.(input.checked);
    });
    return lvxH("label", { class: "lvx-row-check" },
        checkWrap,
        opts.label ? lvxH("span", { text: opts.label }) : null,
    );
}

export function lvxRadio(opts: { checked?: boolean; disabled?: boolean; name: string; label?: string; onChange?: (checked: boolean) => void }): HTMLLabelElement {
    const input = lvxH("input", { type: "radio", name: opts.name }) as HTMLInputElement;
    input.checked = !!opts.checked;
    input.disabled = !!opts.disabled;
    if (opts.onChange) input.addEventListener("change", () => opts.onChange!(input.checked));
    return lvxH("label", { class: "lvx-row-check" },
        lvxH("span", { class: "lvx-radio" }, input, lvxH("span", { class: "lvx-radio__box" })),
        opts.label ? lvxH("span", { text: opts.label }) : null,
    );
}

export interface LvxSegmentedOption { value: string; label: string }

export function lvxSegmented(opts: {
    options: LvxSegmentedOption[];
    value?: string;
    size?: "sm" | "md" | "lg";
    variant?: "brand" | "surface";
    ariaLabel?: string;
    onChange?: (value: string) => void;
}): HTMLDivElement {
    const szCls = opts.size && opts.size !== "md" ? ` lvx-seg--${opts.size}` : "";
    const varCls = opts.variant === "surface" ? " lvx-seg--surface" : "";
    const seg = lvxH("div", { class: `lvx-seg${szCls}${varCls}`, role: "group", ariaLabel: opts.ariaLabel });
    const buttons: HTMLButtonElement[] = [];
    for (const opt of opts.options) {
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-seg__item",
            text: opt.label,
            "aria-pressed": opts.value === opt.value ? "true" : "false",
            onclick: () => {
                for (const b of buttons) b.setAttribute("aria-pressed", b === btn ? "true" : "false");
                opts.onChange?.(opt.value);
            },
        });
        buttons.push(btn);
        seg.appendChild(btn);
    }
    return seg;
}

export function lvxInput(opts: {
    value?: string;
    placeholder?: string;
    type?: string;
    size?: "sm" | "md" | "lg";
    ariaLabel?: string;
    invalid?: boolean;
    disabled?: boolean;
    readOnly?: boolean;
    /** 前缀图标/文本（Semi / AntD / shadcn 风格） */
    prefix?: string;
    /** 是否显示一键清空按钮 */
    clearable?: boolean;
    /** 密码框是否显示明暗文眼睛切换 */
    passwordToggle?: boolean;
    /** 右侧快捷键帽提示（如 "⌘K" / "/"） */
    kbd?: string;
    /** 最大字数计数提示 */
    maxLength?: number;
    onInput?: (value: string) => void;
}): HTMLInputElement {
    const sz = opts.size && opts.size !== "md" ? ` lvx-input--${opts.size}` : "";
    const input = lvxH("input", { type: opts.type || "text", class: `lvx-input${sz}`, placeholder: opts.placeholder, ariaLabel: opts.ariaLabel, disabled: opts.disabled, readonly: opts.readOnly }) as HTMLInputElement;
    if (opts.value !== undefined) input.value = opts.value;
    if (opts.disabled) input.disabled = true;
    if (opts.invalid) input.setAttribute("aria-invalid", "true");
    if (!opts.prefix && !opts.clearable && !opts.passwordToggle && !opts.kbd && !opts.maxLength) {
        if (opts.onInput) input.addEventListener("input", () => opts.onInput!(input.value));
        return input;
    }

    const wrap = lvxH("div", { class: "lvx-input-affix" }) as unknown as HTMLInputElement;
    if (opts.prefix) {
        const isSvg = opts.prefix.trim().startsWith("<");
        wrap.appendChild(lvxH("span", {
            style: { display: "inline-flex", alignItems: "center", color: "var(--lvx-text-muted)", flexShrink: "0" },
            ...(isSvg ? { html: opts.prefix } : { text: opts.prefix }),
        }));
    }
    wrap.appendChild(input);

    const countEl = opts.maxLength ? lvxH("span", {
        style: { fontSize: "11px", color: "var(--lvx-text-muted)", fontVariantNumeric: "tabular-nums", flexShrink: "0" },
        text: `${(input.value || "").length}/${opts.maxLength}`,
    }) : null;
    if (countEl) wrap.appendChild(countEl);

    let updateAffixState: (() => void) | undefined;
    if (opts.clearable) {
        const clrBtn = lvxH("button", {
            type: "button",
            class: "lvx-chip__close",
            style: { width: "18px", height: "18px", fontSize: "11px", display: input.value ? "" : "none" },
            ariaLabel: "清空输入",
            text: "✕",
            onclick: () => {
                input.value = "";
                if (countEl && opts.maxLength) countEl.textContent = `0/${opts.maxLength}`;
                clrBtn.style.display = "none";
                input.focus();
                opts.onInput?.("");
            },
        });
        wrap.appendChild(clrBtn);
        updateAffixState = () => { clrBtn.style.display = input.value ? "" : "none"; };
    }

    if (opts.passwordToggle) {
        let shown = input.type !== "password";
        const eyeIco = () => `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" style="width:14px;height:14px;fill:none;flex-shrink:0;"><path d="${shown ? 'M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24M1 1l22 22' : 'M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6z'}"/></svg>`;
        const eyeBtn = lvxH("button", {
            type: "button",
            style: { border: "none", background: "transparent", color: "var(--lvx-text-muted)", cursor: "pointer", display: "inline-flex", alignItems: "center", padding: "0 2px" },
            ariaLabel: "切换密码可见性",
            html: eyeIco(),
            onclick: () => {
                shown = !shown;
                input.type = shown ? "text" : "password";
                eyeBtn.innerHTML = eyeIco();
            },
        });
        wrap.appendChild(eyeBtn);
    }

    if (opts.kbd) wrap.appendChild(lvxKbd(opts.kbd));

    input.addEventListener("input", () => {
        if (countEl && opts.maxLength) countEl.textContent = `${input.value.length}/${opts.maxLength}`;
        updateAffixState?.();
        opts.onInput?.(input.value);
    });

    try {
        Object.defineProperty(wrap, "value", {
            get: () => input.value,
            set: (v: string) => { input.value = v; },
        });
    } catch { /* ignore in mock DOM */ }
    return wrap;
}

export function lvxTextarea(opts: { value?: string; placeholder?: string; rows?: number; disabled?: boolean; ariaLabel?: string; onInput?: (value: string) => void }): HTMLTextAreaElement {
    const el = lvxH("textarea", { class: "lvx-textarea", placeholder: opts.placeholder, rows: opts.rows, disabled: opts.disabled, ariaLabel: opts.ariaLabel }) as HTMLTextAreaElement;
    if (opts.value !== undefined) el.value = opts.value;
    if (opts.disabled) el.disabled = true;
    if (opts.onInput) el.addEventListener("input", () => opts.onInput!(el.value));
    return el;
}

export function lvxSelect(opts: { options: LvxSegmentedOption[]; value?: string; size?: "sm" | "md" | "lg"; disabled?: boolean; ariaLabel?: string; onChange?: (value: string) => void }): HTMLSelectElement {
    const sz = opts.size && opts.size !== "md" ? ` lvx-select--${opts.size}` : "";
    const select = lvxH("select", { class: `lvx-select${sz}`, disabled: opts.disabled, ariaLabel: opts.ariaLabel }) as HTMLSelectElement;
    if (opts.disabled) select.disabled = true;
    for (const opt of opts.options) {
        const option = lvxH("option", { value: opt.value, text: opt.label }) as HTMLOptionElement;
        select.appendChild(option);
    }
    if (opts.value !== undefined) select.value = opts.value;
    if (opts.onChange) select.addEventListener("change", () => opts.onChange!(select.value));
    return select;
}

/** 表单容器 Field：label + 控件 + 校验错误行（error 非空时进入 is-error 态） */
export function lvxField(opts: { label: string; hint?: string; control: HTMLElement; error?: string }): HTMLDivElement {
    const field = lvxH("div", { class: `lvx-field${opts.error ? " is-error" : ""}` },
        lvxH("label", { class: "lvx-field__label", text: opts.label },
            opts.hint ? lvxH("small", { text: opts.hint }) : null),
        opts.control,
        lvxH("span", { class: "lvx-field__error", text: opts.error || "" }),
    );
    return field;
}

export function lvxEmpty(opts: { icon?: string; mascot?: string; title: string; desc?: string; action?: HTMLElement }): HTMLDivElement {
    return lvxH("div", { class: "lvx-empty" },
        opts.mascot ? lvxH("span", { html: opts.mascot, class: "lvx-empty__mascot" }) : null,
        !opts.mascot && opts.icon ? lvxH("span", { class: "lvx-empty__icon", text: opts.icon }) : null,
        lvxH("span", { class: "lvx-empty__title", text: opts.title }),
        opts.desc ? lvxH("span", { class: "lvx-empty__desc", text: opts.desc }) : null,
        opts.action ? lvxH("span", { class: "lvx-empty__action" }, opts.action) : null,
    );
}

/** 进度条（进度域动效：reduced-motion 只停过渡动画，宽度如实呈现，永不因偏好关闭） */
export function lvxProgress(opts: { value: number; tone?: "brand" | "energy" | "success" | "warn" | "danger"; size?: "sm" | "md" | "lg"; ariaLabel?: string }): HTMLDivElement {
    const pct = Math.max(0, Math.min(100, Math.round(opts.value * 100)));
    const bar = lvxH("div", { class: "lvx-progress__bar", style: { width: `${pct}%` } });
    const toneCls = opts.tone && opts.tone !== "brand" ? ` lvx-progress--${opts.tone}` : "";
    const szCls = opts.size && opts.size !== "md" ? ` lvx-progress--${opts.size}` : "";
    const el = lvxH("div", {
        class: `lvx-progress${toneCls}${szCls}`,
        role: "progressbar",
        ariaLabel: opts.ariaLabel,
        "aria-valuemin": "0",
        "aria-valuemax": "100",
        "aria-valuenow": String(pct),
    }, bar);
    return el;
}

/** Dialog 布局壳：只提供 head/body/foot 结构与 lvx 视觉，不接管思源 Dialog 生命周期 */
export function lvxDialogShell(opts: { title: string; body: Array<LvUiChild | Array<LvUiChild>>; footer?: HTMLElement[]; footerRow?: boolean; onClose?: () => void }): HTMLDivElement {
    const closeBtn = lvxIconButton({ icon: "✕", label: "关闭", onClick: () => opts.onClose?.() });
    return lvxH("div", { class: "lvx-dialog", role: "dialog", ariaLabel: opts.title },
        lvxH("div", { class: "lvx-dialog__head" }, lvxH("span", { text: opts.title }), closeBtn),
        lvxH("div", { class: "lvx-dialog__body" }, ...opts.body),
        opts.footer?.length ? lvxH("div", { class: `lvx-dialog__foot${opts.footerRow ? " lvx-dialog__foot--row" : ""}` }, ...opts.footer) : null,
    );
}

export type LvxSkeletonVariant = "text" | "title" | "circle" | "rect";

/** 骨架屏（加载占位；加载指示域白名单——只随系统 reduced-motion 静态化，永不因外观偏好关闭） */
export function lvxSkeleton(opts: { variant?: LvxSkeletonVariant; width?: number | string; height?: number | string; lines?: number; ariaLabel?: string }): HTMLElement {
    const variant = opts.variant || "text";
    const style: Record<string, string> = {};
    if (opts.width !== undefined) style.width = typeof opts.width === "number" ? `${opts.width}px` : opts.width;
    if (opts.height !== undefined) style.height = typeof opts.height === "number" ? `${opts.height}px` : opts.height;
    const one = () => lvxH("div", { class: `lvx-skeleton lvx-skeleton--${variant}`, style });
    if (variant === "text" && (opts.lines ?? 0) > 1) {
        const group = lvxH("div", { class: "lvx-skeleton-group", role: "status", ariaLabel: opts.ariaLabel || "加载中" });
        const n = opts.lines!;
        for (let i = 0; i < n; i++) {
            const line = lvxH("div", { class: "lvx-skeleton lvx-skeleton--text" });
            if (i === n - 1) line.style.width = "62%";
            group.appendChild(line);
        }
        return group;
    }
    const el = one();
    if (opts.ariaLabel) el.setAttribute("role", "status");
    return el;
}

export type LvxErrorTone = "danger" | "warn";

/** 错误态（错误警示域：本体静态、无装饰动画；role=alert 语义由工厂补足） */
export function lvxErrorState(opts: { icon?: string; title?: string; desc?: string; actions?: HTMLElement[]; tone?: LvxErrorTone; ariaLabel?: string }): HTMLDivElement {
    const tone = opts.tone === "warn" ? " lvx-error--warn" : "";
    const el = lvxH("div", { class: `lvx-error${tone}`, role: "alert", ariaLabel: opts.ariaLabel });
    if (opts.icon) el.appendChild(lvxH("span", { class: "lvx-error__icon", text: opts.icon }));
    if (opts.title) el.appendChild(lvxH("span", { class: "lvx-error__title", text: opts.title }));
    if (opts.desc) el.appendChild(lvxH("span", { class: "lvx-error__desc", text: opts.desc }));
    if (opts.actions?.length) el.appendChild(lvxH("span", { class: "lvx-error__actions" }, ...opts.actions));
    return el;
}

/* ---- v2 第一批工厂 ---- */

export type LvxAlertTone = "brand" | "success" | "warn" | "danger";

/** 信息条（Alert/Callout；静态，无装饰动画，支持 closable 与 actions） */
export function lvxAlert(opts: {
    icon?: string;
    title: string;
    desc?: string;
    tone?: LvxAlertTone;
    closable?: boolean;
    actions?: HTMLElement[];
    onClose?: () => void;
    ariaLabel?: string;
}): HTMLDivElement {
    const tone = opts.tone && opts.tone !== "brand" ? ` lvx-alert--${opts.tone}` : "";
    const el = lvxH("div", { class: `lvx-alert${tone}`, role: "status", ariaLabel: opts.ariaLabel });
    el.appendChild(lvxH("span", { class: "lvx-alert__icon", text: opts.icon || (opts.tone === "success" ? "✓" : opts.tone === "warn" ? "⚠" : opts.tone === "danger" ? "✕" : "ℹ") }));
    const body = lvxH("div", { class: "lvx-alert__body" },
        lvxH("span", { class: "lvx-alert__title", text: opts.title }),
        opts.desc ? lvxH("span", { class: "lvx-alert__desc", text: opts.desc }) : null,
        opts.actions?.length ? lvxH("div", { class: "lvx-alert__actions" }, ...opts.actions) : null);
    el.appendChild(body);
    if (opts.closable) {
        const closeBtn = lvxH("button", {
            type: "button",
            class: "lvx-alert__close",
            text: "✕",
            ariaLabel: "关闭提示",
            onclick: () => {
                el.style.display = "none";
                opts.onClose?.();
            },
        });
        el.appendChild(closeBtn);
    }
    return el;
}

/** 分割线；text 传入时渲染嵌字分割线 */
export function lvxDivider(opts?: { vertical?: boolean; text?: string }): HTMLDivElement {
    if (opts?.text) return lvxH("div", { class: "lvx-divider lvx-divider--text", role: "separator", text: opts.text });
    return lvxH("div", { class: `lvx-divider${opts?.vertical ? " lvx-divider--vertical" : ""}`, role: "separator" });
}

/** Tooltip 包装器：包裹任意触发元素；支持 top/bottom/left/right 四向定位（CSS-only，hover/focus 显形） */
export function lvxTooltip(opts: { tip: string; trigger: HTMLElement; placement?: "top" | "bottom" | "left" | "right" }): HTMLSpanElement {
    const pCls = opts.placement && opts.placement !== "top" ? ` lvx-tooltip--${opts.placement}` : "";
    return lvxH("span", { class: `lvx-tooltip${pCls}`, "data-tip": opts.tip }, opts.trigger);
}

export interface LvxTabOption { id: string; label: string; icon?: string; badge?: string | number }

/** 页签结构（aria-selected 语义 + 键盘左右方向键切换 + 图标/计数角标支持） */
export function lvxTabs(opts: { options: LvxTabOption[]; value?: string; ariaLabel?: string; onChange?: (id: string) => void }): HTMLDivElement {
    const list = lvxH("div", { class: "lvx-tabs__list", role: "tablist", ariaLabel: opts.ariaLabel });
    const buttons: HTMLButtonElement[] = [];
    let activeIdx = Math.max(0, opts.options.findIndex(o => o.id === opts.value));

    const selectAt = (idx: number) => {
        if (idx < 0 || idx >= buttons.length) return;
        activeIdx = idx;
        buttons.forEach((b, i) => b.setAttribute("aria-selected", i === idx ? "true" : "false"));
        buttons[idx]?.focus?.();
        const targetOpt = opts.options[idx];
        if (targetOpt) opts.onChange?.(targetOpt.id);
    };

    opts.options.forEach((opt, idx) => {
        const hasExtra = opt.icon !== undefined || opt.badge !== undefined;
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-tabs__tab",
            role: "tab",
            text: hasExtra ? undefined : opt.label,
            "aria-selected": opts.value === opt.id ? "true" : "false",
            onclick: () => selectAt(idx),
        });
        if (hasExtra) {
            if (opt.icon) btn.appendChild(lvxH("span", { text: opt.icon, "aria-hidden": "true" }));
            btn.appendChild(lvxH("span", { text: opt.label }));
            if (opt.badge !== undefined) btn.appendChild(lvxH("span", { class: "lvx-tabs__badge", text: String(opt.badge) }));
        }
        buttons.push(btn);
        list.appendChild(btn);
    });

    list.addEventListener("keydown", (ev: KeyboardEvent) => {
        if (!buttons.length) return;
        if (ev.key === "ArrowRight") {
            ev.preventDefault?.();
            selectAt((activeIdx + 1) % buttons.length);
        } else if (ev.key === "ArrowLeft") {
            ev.preventDefault?.();
            selectAt((activeIdx - 1 + buttons.length) % buttons.length);
        }
    });

    return list;
}

export interface LvxPaginationPage { label: string; page?: number; current?: boolean; disabled?: boolean; ellipsis?: boolean }

/** 页码组（aria-current 页语义；点击回调带页码，ellipsis 项不回调） */
export function lvxPagination(opts: { pages: LvxPaginationPage[]; onChange?: (page: number) => void; ariaLabel?: string }): HTMLDivElement {
    const nav = lvxH("div", { class: "lvx-pagination", role: "navigation", ariaLabel: opts.ariaLabel || "分页" });
    const btns: HTMLButtonElement[] = [];
    for (const pg of opts.pages) {
        if (pg.ellipsis) {
            nav.appendChild(lvxH("span", { class: "lvx-pagination__ellipsis", text: pg.label || "…" }));
            continue;
        }
        const isPrev = pg.label === "‹" || pg.label === "前页";
        const isNext = pg.label === "›" || pg.label === "后页";
        const btnChild = isPrev ? lvxH("span", { style: { display: "inline-flex", lineHeight: "0" }, html: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>' })
            : isNext ? lvxH("span", { style: { display: "inline-flex", lineHeight: "0" }, html: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>' })
            : pg.label;
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-pagination__page",
            text: (!isPrev && !isNext) ? pg.label : undefined,
            disabled: pg.disabled,
            "aria-current": pg.current ? "page" : undefined,
            ariaLabel: pg.page !== undefined ? `第 ${pg.page} 页` : undefined,
            onclick: () => {
                if (pg.disabled || pg.page === undefined) return;
                for (const b of btns) b.setAttribute("aria-current", b === btn ? "page" : "false");
                opts.onChange?.(pg.page);
            },
        }, (isPrev || isNext) ? btnChild : undefined);
        btns.push(btn);
        nav.appendChild(btn);
    }
    return nav;
}

export interface LvxBreadcrumbItem { label: string; current?: boolean; onClick?: () => void }

/* ---- v2 第二批工厂 ---- */

export type LvxResultTone = "success" | "error" | "warning" | "info";

/** 结果页（大图标 + 标题 + 描述 + 操作；tone 决定图标语义色，icon 可覆盖） */
export function lvxResult(opts: { tone?: LvxResultTone; icon?: string; title: string; desc?: string; actions?: HTMLElement[]; ariaLabel?: string }): HTMLDivElement {
    const tone = opts.tone || "info";
    const icon = opts.icon || ({ success: "✓", error: "✕", warning: "⚠", info: "ℹ" } as Record<LvxResultTone, string>)[tone];
    return lvxH("div", { class: `lvx-result lvx-result--${tone}`, role: "status", ariaLabel: opts.ariaLabel },
        lvxH("span", { class: "lvx-result__icon", text: icon }),
        lvxH("span", { class: "lvx-result__title", text: opts.title }),
        opts.desc ? lvxH("span", { class: "lvx-result__desc", text: opts.desc }) : null,
        opts.actions?.length ? lvxH("span", { class: "lvx-result__actions" }, ...opts.actions) : null);
}

export interface LvxDrawerSection { title?: string; body: Array<LvUiChild | Array<LvUiChild>>; footer?: HTMLElement[]; onClose?: () => void }

/**
 * 抽屉（mask+panel 一体）：返回 mask 根；开合由使用方切换根的 data-open="true|false"。
 * side="left" 时从左侧滑入（默认右侧）。
 */
export function lvxDrawer(opts: LvxDrawerSection & { side?: "right" | "left" }): HTMLDivElement {
    const closeBtn = lvxIconButton({ icon: "✕", label: "关闭", onClick: () => opts.onClose?.() });
    const mask = lvxH("div", { "data-open": "false", role: "dialog", ariaLabel: opts.title || "抽屉" },
        lvxH("div", { class: "lvx-drawer-mask", "aria-hidden": "true", onclick: () => opts.onClose?.() }),
        lvxH("div", { class: `lvx-drawer${opts.side === "left" ? " lvx-drawer--left" : ""}` },
            lvxH("div", { class: "lvx-drawer__head" }, lvxH("span", { text: opts.title || "" }), closeBtn),
            lvxH("div", { class: "lvx-drawer__body" }, ...opts.body),
            opts.footer?.length ? lvxH("div", { class: "lvx-drawer__foot" }, ...opts.footer) : null));
    return mask;
}

/** 气泡卡（默认隐藏；使用方控制 data-open="true" 显隐与定位） */
export function lvxPopover(opts: { content: Array<LvUiChild | Array<LvUiChild>>; ariaLabel?: string }): HTMLDivElement {
    return lvxH("div", { class: "lvx-popover", "data-open": "false", role: "dialog", ariaLabel: opts.ariaLabel }, ...opts.content);
}

/** 滑杆（range 表单皮肤；轨道按 --lvx-slider-pct 自动填充品牌色） */
export function lvxSlider(opts: { value?: number; min?: number; max?: number; step?: number; ariaLabel?: string; disabled?: boolean; onInput?: (value: number) => void }): HTMLInputElement {
    const min = opts.min ?? 0;
    const max = opts.max ?? 100;
    const val = opts.value ?? 50;
    const input = lvxH("input", {
        type: "range",
        class: "lvx-slider",
        min,
        max,
        step: opts.step ?? 1,
        ariaLabel: opts.ariaLabel,
    }) as HTMLInputElement;
    if (opts.value !== undefined) input.value = String(opts.value);
    input.disabled = !!opts.disabled;
    const syncPct = (v: number) => {
        const pct = max > min ? Math.max(0, Math.min(100, Math.round(((v - min) / (max - min)) * 100))) : 0;
        if (typeof input.style?.setProperty === "function") input.style.setProperty("--lvx-slider-pct", `${pct}%`);
        else if (input.style) (input.style as any)["--lvx-slider-pct"] = `${pct}%`;
    };
    syncPct(val);
    input.addEventListener("input", () => {
        const num = Number(input.value);
        syncPct(num);
        opts.onInput?.(num);
    });
    return input;
}

export interface LvxMenuItem { label?: string; icon?: string; danger?: boolean; divider?: boolean; groupLabel?: string; onClick?: () => void }

/** 菜单（下拉/上下文通用；divider/groupLabel/danger 变体；显隐与定位由使用方控制） */
export function lvxMenu(opts: { items: LvxMenuItem[]; ariaLabel?: string }): HTMLDivElement {
    const menu = lvxH("div", { class: "lvx-menu", role: "menu", ariaLabel: opts.ariaLabel });
    for (const item of opts.items) {
        if (item.divider) {
            menu.appendChild(lvxH("div", { class: "lvx-menu__divider", role: "separator" }));
            continue;
        }
        if (item.groupLabel !== undefined) {
            menu.appendChild(lvxH("span", { class: "lvx-menu__label", text: item.groupLabel }));
            continue;
        }
        menu.appendChild(lvxH("button", {
            type: "button",
            class: `lvx-menu__item${item.danger ? " lvx-menu__item--danger" : ""}`,
            role: "menuitem",
            onclick: item.onClick,
        },
            item.icon ? lvxH("span", { text: item.icon }) : null,
            lvxH("span", { text: item.label || "" })));
    }
    return menu;
}

/** 面包屑（尾项 aria-current；分隔符由 CSS ::before 自动注入；支持 capsule / plain 变体） */
export function lvxBreadcrumb(opts: { items: LvxBreadcrumbItem[]; variant?: "capsule" | "plain"; ariaLabel?: string }): HTMLElement {
    const vCls = opts.variant === "plain" ? " lvx-breadcrumb--plain" : "";
    const nav = lvxH("nav", { class: `lvx-breadcrumb${vCls}`, ariaLabel: opts.ariaLabel || "面包屑" });
    for (const item of opts.items) {
        nav.appendChild(lvxH(item.onClick ? "button" : "span", {
            type: item.onClick ? "button" : undefined,
            class: "lvx-breadcrumb__item",
            text: item.label,
            "aria-current": item.current ? "page" : undefined,
            onclick: item.onClick,
        }));
    }
    return nav;
}

/* ---- v2 第三批工厂：Timeline / List / Table / Combobox ---- */

export type LvxTimelineTone = "brand" | "energy" | "success" | "muted";
export interface LvxTimelineItem {
    title: string;
    time?: string;
    content?: string | HTMLElement;
    tone?: LvxTimelineTone;
}

/** 时间线（垂直轴线 + 节点 dot + 标题 + 内容；支持四 tone） */
export function lvxTimeline(opts: { items: LvxTimelineItem[]; ariaLabel?: string }): HTMLDivElement {
    const list = lvxH("div", { class: "lvx-timeline", role: "list", ariaLabel: opts.ariaLabel });
    for (const item of opts.items) {
        const toneClass = item.tone && item.tone !== "brand" ? ` lvx-timeline__dot--${item.tone}` : "";
        const dot = lvxH("span", { class: `lvx-timeline__dot${toneClass}`, "aria-hidden": "true" });
        const head = lvxH("div", { class: "lvx-timeline__head" },
            lvxH("span", { text: item.title }),
            item.time ? lvxH("span", { class: "lvx-timeline__time", text: item.time }) : null);
        let body: HTMLElement | null = null;
        if (typeof item.content === "string") {
            body = lvxH("div", { class: "lvx-timeline__content", text: item.content });
        } else if (item.content) {
            body = lvxH("div", { class: "lvx-timeline__content" }, item.content);
        }
        const itemEl = lvxH("div", { class: "lvx-timeline__item", role: "listitem" }, dot, head, body);
        list.appendChild(itemEl);
    }
    return list;
}

export interface LvxListItemOptions {
    title: string;
    desc?: string;
    prefix?: HTMLElement | string;
    suffix?: HTMLElement | string;
    interactive?: boolean;
    onClick?: () => void;
    ariaLabel?: string;
}

/** 列表项（通用前缀/主体/后缀结构；可交互变体 hover/active） */
export function lvxListItem(opts: LvxListItemOptions): HTMLElement {
    const interactive = opts.interactive || !!opts.onClick;
    const tag = interactive ? "button" : "div";
    const item = lvxH(tag, {
        type: interactive ? "button" : undefined,
        class: `lvx-list-item${interactive ? " lvx-list-item--interactive" : ""}`,
        role: interactive ? undefined : "listitem",
        ariaLabel: opts.ariaLabel,
        onclick: opts.onClick,
        style: { textAlign: "left", width: "100%" },
    });
    if (opts.prefix) {
        const prefixEl = typeof opts.prefix === "string" ? lvxH("span", { class: "lvx-list-item__prefix", text: opts.prefix }) : lvxH("span", { class: "lvx-list-item__prefix" }, opts.prefix);
        item.appendChild(prefixEl);
    }
    const main = lvxH("div", { class: "lvx-list-item__main" },
        lvxH("span", { class: "lvx-list-item__title", text: opts.title }),
        opts.desc ? lvxH("span", { class: "lvx-list-item__desc", text: opts.desc }) : null);
    item.appendChild(main);
    if (opts.suffix) {
        const suffixEl = typeof opts.suffix === "string" ? lvxH("span", { class: "lvx-list-item__suffix", text: opts.suffix }) : lvxH("span", { class: "lvx-list-item__suffix" }, opts.suffix);
        item.appendChild(suffixEl);
    }
    return item;
}

/** 列表容器（语义 role=list） */
export function lvxList(opts: { items: HTMLElement[]; ariaLabel?: string }): HTMLDivElement {
    return lvxH("div", { class: "lvx-list", role: "list", ariaLabel: opts.ariaLabel }, ...opts.items);
}

export interface LvxTableColumn {
    key: string;
    title: string;
    width?: string | number;
    align?: "left" | "center" | "right";
    /** 是否支持点击列头升/降序重排（AntD / TanStack Table 风格） */
    sortable?: boolean;
}

/** 数据表格（响应式包裹 + 双主题交替/悬浮行 + 紧凑变体 + 列头点击排序） */
export function lvxTable(opts: { columns: LvxTableColumn[]; rows: Array<Record<string, string | number | HTMLElement>>; compact?: boolean; ariaLabel?: string }): HTMLDivElement {
    let sortKey = "";
    let sortDir: "asc" | "desc" = "asc";
    const wrap = lvxH("div", { class: "lvx-table-wrap" });
    const table = lvxH("table", {
        class: `lvx-table${opts.compact ? " lvx-table--compact" : ""}`,
        ariaLabel: opts.ariaLabel,
    });
    const thead = lvxH("thead", {});
    const headerRow = lvxH("tr", {});
    const tbody = lvxH("tbody", {});

    const renderBody = () => {
        tbody.innerHTML = "";
        const sorted = [...opts.rows];
        if (sortKey) {
            sorted.sort((a, b) => {
                const va = a[sortKey];
                const vb = b[sortKey];
                const sa = typeof va === "number" ? va : parseFloat(String(va)) || String(va);
                const sb = typeof vb === "number" ? vb : parseFloat(String(vb)) || String(vb);
                const cmp = sa < sb ? -1 : sa > sb ? 1 : 0;
                return sortDir === "asc" ? cmp : -cmp;
            });
        }
        for (const rowData of sorted) {
            const tr = lvxH("tr", {});
            for (const col of opts.columns) {
                const cellVal = rowData[col.key];
                const td = lvxH("td", { style: col.align ? { textAlign: col.align, fontVariantNumeric: "tabular-nums" } : undefined });
                if (cellVal && typeof cellVal === "object" && ("nodeType" in (cellVal as any) || "tagName" in (cellVal as any))) {
                    td.appendChild(cellVal as HTMLElement);
                } else {
                    td.textContent = cellVal !== undefined ? String(cellVal) : "";
                }
                tr.appendChild(td);
            }
            tbody.appendChild(tr);
        }
    };

    for (const col of opts.columns) {
        const style: Record<string, string> = {};
        if (col.width) style.width = typeof col.width === "number" ? `${col.width}px` : col.width;
        if (col.align) style.textAlign = col.align;
        if (col.sortable) style.cursor = "pointer";
        const th = lvxH("th", { text: col.sortable ? `${col.title} ⇅` : col.title, style });
        if (col.sortable) {
            th.dataset.colKey = col.key;
            th.dataset.colTitle = col.title;
            th.tabIndex = 0;
            th.setAttribute("aria-sort", "none");
            th.addEventListener("keydown", (ev: KeyboardEvent) => {
                if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); th.click(); }
            });
            th.addEventListener("click", () => {
                if (sortKey === col.key) sortDir = sortDir === "asc" ? "desc" : "asc";
                else { sortKey = col.key; sortDir = "asc"; }
                headerRow.querySelectorAll("th[data-col-key]").forEach((h: any) => {
                    if (h.dataset.colKey === col.key) {
                        h.textContent = `${col.title} ${sortDir === "asc" ? "↑" : "↓"}`;
                        h.setAttribute("aria-sort", sortDir === "asc" ? "ascending" : "descending");
                    } else {
                        h.textContent = `${h.dataset.colTitle} ⇅`;
                        h.setAttribute("aria-sort", "none");
                    }
                });
                renderBody();
            });
        }
        headerRow.appendChild(th);
    }
    thead.appendChild(headerRow);
    table.appendChild(thead);
    renderBody();
    table.appendChild(tbody);
    wrap.appendChild(table);
    return wrap;
}

export interface LvxComboboxOption {
    value: string;
    label: string;
}

/** 组合下拉选择框（输入搜索 + 快捷下拉选择 + 一键清空 + 空匹配提示） */
export function lvxCombobox(opts: {
    options: LvxComboboxOption[];
    value?: string;
    placeholder?: string;
    clearable?: boolean;
    ariaLabel?: string;
    onChange?: (val: string) => void;
}): HTMLDivElement {
    const box = lvxH("div", { class: "lvx-combobox", "data-open": "false" });
    const currentOpt = opts.options.find(o => o.value === opts.value);
    const input = lvxH("input", {
        type: "text",
        class: "lvx-combobox__input",
        placeholder: opts.placeholder || "请选择...",
        ariaLabel: opts.ariaLabel,
        value: currentOpt ? currentOpt.label : "",
    }) as HTMLInputElement;
    input.setAttribute("role", "combobox");
    input.setAttribute("aria-expanded", "false");
    input.addEventListener("focus", () => input.setAttribute("aria-expanded", "true"));
    input.addEventListener("blur", () => input.setAttribute("aria-expanded", "false"));

    const arrow = lvxH("span", { class: "lvx-combobox__arrow", text: "▼", "aria-hidden": "true" });
    const dropdown = lvxH("div", { class: "lvx-combobox__dropdown", role: "listbox" });

    function renderOptions(filterText = "") {
        dropdown.innerHTML = "";
        const lower = filterText.toLowerCase();
        const filtered = opts.options.filter(o => !lower || o.label.toLowerCase().includes(lower));
        if (!filtered.length) {
            dropdown.appendChild(lvxH("div", { class: "lvx-combobox__empty", text: "无匹配选项" }));
            return;
        }
        for (const opt of filtered) {
            const btn = lvxH("button", {
                type: "button",
                class: "lvx-combobox__option",
                role: "option",
                "aria-selected": opt.value === opts.value ? "true" : "false",
                text: opt.label,
                onclick: () => {
                    input.value = opt.label;
                    box.setAttribute("data-open", "false");
                    input.setAttribute("aria-expanded", "false");
                    opts.value = opt.value;
                    renderOptions();
                    opts.onChange?.(opt.value);
                },
            });
            dropdown.appendChild(btn);
        }
    }
    renderOptions();

    const dismissCtrl = setupOverlayDismiss(box, () => {
        if (!input.value && opts.value) {
            const cur = opts.options.find(o => o.value === opts.value);
            if (cur) input.value = cur.label;
        }
    }, [input, arrow]);

    input.addEventListener("focus", () => {
        dismissCtrl.open();
        renderOptions();
    });
    input.addEventListener("input", () => {
        dismissCtrl.open();
        renderOptions(input.value);
    });

    box.appendChild(input);
    if (opts.clearable) {
        const clearBtn = lvxH("button", {
            type: "button",
            class: "lvx-combobox__clear",
            text: "✕",
            ariaLabel: "清空选择",
            onclick: () => {
                input.value = "";
                opts.value = "";
                renderOptions("");
                opts.onChange?.("");
            },
        });
        box.appendChild(clearBtn);
    }
    box.appendChild(arrow);
    box.appendChild(dropdown);
    return box;
}

/* ---- v2 第四批工厂：Tree / Calendar / TimePicker ---- */

export interface LvxTreeNode {
    id: string;
    label: string;
    icon?: string;
    badge?: string | number;
    children?: LvxTreeNode[];
    expanded?: boolean;
    selected?: boolean;
}

/** 树形层级（递归节点 + 展开/折叠 + 选中高亮；role=tree） */
export function lvxTree(opts: {
    nodes: LvxTreeNode[];
    ariaLabel?: string;
    onSelect?: (node: LvxTreeNode) => void;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-tree", role: "tree", ariaLabel: opts.ariaLabel });
    const allBtns: HTMLButtonElement[] = [];

    function renderNode(node: LvxTreeNode, level = 0): HTMLElement[] {
        const hasChildren = !!node.children?.length;
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-tree__node",
            role: "treeitem",
            style: { paddingLeft: `${8 + level * 16}px` },
            "aria-expanded": hasChildren ? (node.expanded ? "true" : "false") : undefined,
            "aria-selected": node.selected ? "true" : "false",
        });
        allBtns.push(btn);

        const arrow = lvxH("span", {
            class: "lvx-tree__arrow",
            text: hasChildren ? "▶" : "",
            "aria-hidden": "true",
        });
        btn.appendChild(arrow);

        if (node.icon) {
            btn.appendChild(lvxH("span", { class: "lvx-tree__icon", text: node.icon }));
        }
        btn.appendChild(lvxH("span", { class: "lvx-tree__label", text: node.label }));
        if (node.badge !== undefined) {
            btn.appendChild(lvxH("span", { class: "lvx-tree__badge", text: String(node.badge) }));
        }

        const childContainer = hasChildren ? lvxH("div", {
            class: "lvx-tree__group",
            role: "group",
            style: { display: node.expanded ? "flex" : "none", flexDirection: "column", gap: "1px" },
        }) : null;

        btn.addEventListener("click", () => {
            for (const b of allBtns) b.setAttribute("aria-selected", b === btn ? "true" : "false");
            if (hasChildren) {
                node.expanded = !node.expanded;
                btn.setAttribute("aria-expanded", node.expanded ? "true" : "false");
                if (childContainer) childContainer.style.display = node.expanded ? "flex" : "none";
            }
            opts.onSelect?.(node);
        });

        if (hasChildren && childContainer) {
            for (const ch of node.children!) {
                for (const el of renderNode(ch, level + 1)) {
                    childContainer.appendChild(el);
                }
            }
            return [btn, childContainer];
        }
        return [btn];
    }

    for (const n of opts.nodes) {
        for (const el of renderNode(n, 0)) {
            root.appendChild(el);
        }
    }
    return root;
}

/** 日历网格（零依赖纯计算；支持 sm/md/lg 多尺寸 + 月份翻页 + 今天跳回 + 事件色点 + 选中回调） */
export function lvxCalendar(opts: {
    year?: number;
    month?: number; // 1-12
    selectedDate?: string; // YYYY-MM-DD
    size?: "sm" | "md" | "lg";
    dots?: Record<string, "brand" | "energy" | "success">;
    ariaLabel?: string;
    onSelectDate?: (dateStr: string) => void;
}): HTMLDivElement {
    const now = new Date();
    let currentYear = opts.year || now.getFullYear();
    let currentMonth = opts.month || (now.getMonth() + 1);
    let selected = opts.selectedDate || "";

    const szCls = opts.size && opts.size !== "md" ? ` lvx-calendar--${opts.size}` : "";
    const card = lvxH("div", { class: `lvx-calendar${szCls}`, role: "region", ariaLabel: opts.ariaLabel || "日历" });
    const head = lvxH("div", { class: "lvx-calendar__head" });
    const prevBtn = lvxButton({ label: "‹", sm: true });
    const title = lvxH("span", { text: "" });
    const todayBtn = lvxButton({ label: "今", sm: true, variant: "ghost", ariaLabel: "回到今天" });
    const nextBtn = lvxButton({ label: "›", sm: true });
    const rightCtrls = lvxH("span", { style: { display: "inline-flex", gap: "4px" } }, todayBtn, nextBtn);
    head.appendChild(prevBtn);
    head.appendChild(title);
    head.appendChild(rightCtrls);
    card.appendChild(head);

    const weekdays = ["一", "二", "三", "四", "五", "六", "日"];
    const weekRow = lvxH("div", { class: "lvx-calendar__weekdays" });
    for (const w of weekdays) {
        weekRow.appendChild(lvxH("span", { class: "lvx-calendar__weekday", text: w }));
    }
    card.appendChild(weekRow);

    const grid = lvxH("div", { class: "lvx-calendar__grid" });
    card.appendChild(grid);

    const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;

    function renderMonth() {
        title.textContent = `${currentYear}年${currentMonth}月`;
        grid.innerHTML = "";
        const firstDay = new Date(currentYear, currentMonth - 1, 1);
        let startDayOfWeek = firstDay.getDay(); // 0 is Sunday
        if (startDayOfWeek === 0) startDayOfWeek = 7;
        const totalDays = new Date(currentYear, currentMonth, 0).getDate();

        // blanks for preceding days
        for (let i = 1; i < startDayOfWeek; i++) {
            grid.appendChild(lvxH("span", { class: "lvx-calendar__day lvx-calendar__day--outside", text: "" }));
        }

        for (let d = 1; d <= totalDays; d++) {
            const dateStr = `${currentYear}-${String(currentMonth).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
            const isToday = dateStr === todayStr;
            const isSelected = dateStr === selected;
            let cls = "lvx-calendar__day";
            if (isToday) cls += " lvx-calendar__day--today";
            if (isSelected) cls += " lvx-calendar__day--selected";

            const dotTone = opts.dots?.[dateStr];
            const btn = lvxH("button", {
                type: "button",
                class: cls,
                text: String(d),
                onclick: () => {
                    selected = dateStr;
                    renderMonth();
                    opts.onSelectDate?.(dateStr);
                },
            });
            if (dotTone) {
                const dotCls = dotTone !== "energy" ? ` lvx-calendar__dot--${dotTone}` : "";
                btn.appendChild(lvxH("span", { class: `lvx-calendar__dot${dotCls}`, "aria-hidden": "true" }));
            }
            grid.appendChild(btn);
        }
    }

    prevBtn.onclick = () => {
        currentMonth--;
        if (currentMonth < 1) { currentMonth = 12; currentYear--; }
        renderMonth();
    };
    nextBtn.onclick = () => {
        currentMonth++;
        if (currentMonth > 12) { currentMonth = 1; currentYear++; }
        renderMonth();
    };
    todayBtn.onclick = () => {
        currentYear = now.getFullYear();
        currentMonth = now.getMonth() + 1;
        selected = todayStr;
        renderMonth();
        opts.onSelectDate?.(todayStr);
    };

    renderMonth();
    return card;
}

/** 时间选择器（时:分 快捷面板与输入联动 + 底部确定按钮） */
export function lvxTimePicker(opts: {
    value?: string; // HH:mm
    ariaLabel?: string;
    onChange?: (timeStr: string) => void;
}): HTMLDivElement {
    const wrap = lvxH("div", { class: "lvx-timepicker", "data-open": "false" });
    const input = lvxH("input", {
        type: "text",
        class: "lvx-timepicker__input",
        placeholder: "00:00",
        value: opts.value || "09:00",
        ariaLabel: opts.ariaLabel || "时间",
    }) as HTMLInputElement;

    const popover = lvxH("div", { class: "lvx-timepicker__popover" });
    const colsWrap = lvxH("div", { class: "lvx-timepicker__cols" });
    const hourCol = lvxH("div", { class: "lvx-timepicker__col" });
    const minCol = lvxH("div", { class: "lvx-timepicker__col" });

    let [curH, curM] = (input.value || "09:00").split(":");
    curH = curH || "09";
    curM = curM || "00";

    const hourBtns: HTMLButtonElement[] = [];
    const minBtns: HTMLButtonElement[] = [];

    for (let h = 0; h < 24; h++) {
        const hs = String(h).padStart(2, "0");
        const cell = lvxH("button", {
            type: "button",
            class: "lvx-timepicker__cell",
            text: hs,
            "aria-selected": hs === curH ? "true" : "false",
            onclick: () => {
                curH = hs;
                for (const b of hourBtns) b.setAttribute("aria-selected", b === cell ? "true" : "false");
                input.value = `${curH}:${curM}`;
                opts.onChange?.(input.value);
            },
        });
        hourBtns.push(cell);
        hourCol.appendChild(cell);
    }

    for (let m = 0; m < 60; m += 5) {
        const ms = String(m).padStart(2, "0");
        const cell = lvxH("button", {
            type: "button",
            class: "lvx-timepicker__cell",
            text: ms,
            "aria-selected": ms === curM ? "true" : "false",
            onclick: () => {
                curM = ms;
                for (const b of minBtns) b.setAttribute("aria-selected", b === cell ? "true" : "false");
                input.value = `${curH}:${curM}`;
                dismissCtrl.close();
                opts.onChange?.(input.value);
            },
        });
        minBtns.push(cell);
        minCol.appendChild(cell);
    }

    const dismissCtrl = setupOverlayDismiss(wrap, () => {}, [input]);
    input.addEventListener("focus", () => dismissCtrl.open());
    input.addEventListener("click", () => {
        if (wrap.getAttribute("data-open") === "true") dismissCtrl.close();
        else dismissCtrl.open();
    });

    colsWrap.appendChild(hourCol);
    colsWrap.appendChild(minCol);
    const foot = lvxH("div", { class: "lvx-timepicker__foot" },
        lvxButton({
            label: "确定",
            variant: "primary",
            sm: true,
            block: true,
            onClick: () => wrap.setAttribute("data-open", "false"),
        }),
    );
    popover.appendChild(colsWrap);
    popover.appendChild(foot);
    wrap.appendChild(input);
    wrap.appendChild(popover);
    return wrap;
}

/* ========================================================================= */
/* 12. v3 生态专项工厂（11 组件，补满 DL2 §4.4 48+ 品类矩阵）                   */
/* ========================================================================= */

/** 机械立体感按键标签（支持单键或组合键数组，如 ["Ctrl", "K"]） */
export function lvxKbd(keys: string | string[]): HTMLElement {
    if (typeof keys === "string") {
        return lvxH("kbd", { class: "lvx-kbd", text: keys });
    }
    const group = lvxH("span", { class: "lvx-kbd-group" });
    keys.forEach((k, idx) => {
        if (idx > 0) group.appendChild(lvxH("span", { class: "lvx-kbd-plus", text: "+" }));
        group.appendChild(lvxH("kbd", { class: "lvx-kbd", text: k }));
    });
    return group;
}

/** 暖橘能量星级评分（点击打分 + 分值标签显示） */
export function lvxRate(opts: {
    value?: number;
    max?: number;
    showScore?: boolean;
    disabled?: boolean;
    ariaLabel?: string;
    onChange?: (val: number) => void;
}): HTMLDivElement {
    const max = opts.max ?? 5;
    let current = opts.value ?? 0;
    const wrap = lvxH("div", { class: "lvx-rate", role: "radiogroup", ariaLabel: opts.ariaLabel || "星级评分" });
    if (opts.disabled) wrap.style.opacity = ".45";
    const stars: HTMLButtonElement[] = [];
    const scoreEl = opts.showScore !== false ? lvxH("span", { class: "lvx-rate__score", text: `${current}.0` }) : null;

    const syncStars = (v: number) => {
        stars.forEach((btn, idx) => {
            const active = idx < v;
            btn.setAttribute("aria-checked", active ? "true" : "false");
            btn.className = `lvx-rate__star${active ? " is-active" : ""}`;
        });
        if (scoreEl) scoreEl.textContent = `${v}.0`;
    };

    for (let i = 1; i <= max; i++) {
        const star = lvxH("button", {
            type: "button",
            class: `lvx-rate__star${i <= current ? " is-active" : ""}`,
            role: "radio",
            "aria-checked": i <= current ? "true" : "false",
            ariaLabel: `${i} 星`,
            disabled: opts.disabled,
            text: "★",
            onclick: () => {
                if (opts.disabled) return;
                current = i;
                syncStars(current);
                opts.onChange?.(current);
            },
        });
        stars.push(star);
        wrap.appendChild(star);
    }
    if (scoreEl) wrap.appendChild(scoreEl);
    return wrap;
}

/** 胶囊数值步进器（min/max 边界钳制 + 单位后缀） */
export function lvxStepper(opts: {
    value?: number;
    min?: number;
    max?: number;
    step?: number;
    unit?: string;
    ariaLabel?: string;
    onChange?: (val: number) => void;
}): HTMLDivElement {
    const min = opts.min ?? 0;
    const max = opts.max ?? 100;
    const step = opts.step ?? 1;
    let val = Math.max(min, Math.min(max, opts.value ?? min));

    const valEl = lvxH("span", { class: "lvx-stepper__val", text: `${val}${opts.unit || ""}` });
    const decBtn = lvxH("button", { type: "button", class: "lvx-stepper__btn", text: "−", ariaLabel: "减少" }) as HTMLButtonElement;
    const incBtn = lvxH("button", { type: "button", class: "lvx-stepper__btn", text: "+", ariaLabel: "增加" }) as HTMLButtonElement;

    const sync = () => {
        valEl.textContent = `${val}${opts.unit || ""}`;
        decBtn.disabled = val <= min;
        incBtn.disabled = val >= max;
    };
    decBtn.addEventListener("click", () => {
        if (val <= min) return;
        val = Math.max(min, val - step);
        sync();
        opts.onChange?.(val);
    });
    incBtn.addEventListener("click", () => {
        if (val >= max) return;
        val = Math.min(max, val + step);
        sync();
        opts.onChange?.(val);
    });
    sync();

    return lvxH("div", { class: "lvx-stepper", role: "group", ariaLabel: opts.ariaLabel || "步进器" }, decBtn, valEl, incBtn);
}

export interface LvxStepItem { title: string; desc?: string }

/** 流程步骤条（done / active / pending 三态联动） */
export function lvxSteps(opts: {
    steps: LvxStepItem[];
    current?: number;
    ariaLabel?: string;
    onStepClick?: (idx: number) => void;
}): HTMLDivElement {
    let cur = opts.current ?? 0;
    const wrap = lvxH("div", { class: "lvx-steps", role: "list", ariaLabel: opts.ariaLabel || "步骤条" });
    const itemEls: Array<{ btn: HTMLButtonElement; idxEl: HTMLSpanElement }> = [];

    const sync = () => {
        itemEls.forEach((entry, i) => {
            const state = i < cur ? "done" : i === cur ? "active" : "pending";
            entry.btn.setAttribute("data-state", state);
            entry.btn.setAttribute("aria-current", i === cur ? "step" : "false");
            entry.idxEl.textContent = i < cur ? "✓" : String(i + 1);
        });
    };

    opts.steps.forEach((st, i) => {
        if (i > 0) wrap.appendChild(lvxH("span", { class: "lvx-steps__line", "aria-hidden": "true" }));
        const idxEl = lvxH("span", { class: "lvx-steps__idx", text: String(i + 1) });
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-steps__item",
            onclick: () => {
                cur = i;
                sync();
                opts.onStepClick?.(i);
            },
        }, idxEl, lvxH("span", { text: st.title }));
        itemEls.push({ btn, idxEl });
        wrap.appendChild(btn);
    });
    sync();
    return wrap;
}

/**
 * DL2 标志性图表组件 Sparkline（DL2-PLAN §2 第五维度：
 * 虚线网格 + 柔和三次贝塞尔曲线 + 面积渐变 + 圆点节点 + 虚线「当前时刻」竖线）
 */
let lvxSparklineSeq = 0;

export function lvxSparkline(opts: {
    data: number[];
    labels?: string[];
    width?: number;
    height?: number;
    tone?: "brand" | "energy" | "success";
    currentIndex?: number;
    showSummary?: boolean;
    unit?: string;
    ariaLabel?: string;
}): HTMLDivElement {
    const w = opts.width ?? 320;
    const h = opts.height ?? 110;
    const padX = 14;
    const padY = 14;
    const pts = opts.data.length ? opts.data : [0, 0];
    const minVal = Math.min(...pts);
    const maxVal = Math.max(...pts, minVal + 1);
    const innerW = w - padX * 2;
    const innerH = h - padY * 2;

    const coords = pts.map((v, i) => {
        const x = padX + (pts.length > 1 ? (i / (pts.length - 1)) * innerW : innerW / 2);
        const y = padY + innerH - ((v - minVal) / (maxVal - minVal)) * innerH;
        return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10, v };
    });

    // 构建平滑三次贝塞尔路径
    const firstCoord = coords[0] || { x: padX, y: h / 2, v: 0 };
    let dPath = `M ${firstCoord.x} ${firstCoord.y}`;
    for (let i = 0; i < coords.length - 1; i++) {
        const p0 = coords[i]!;
        const p1 = coords[i + 1]!;
        const cx = Math.round(((p0.x + p1.x) / 2) * 10) / 10;
        dPath += ` C ${cx} ${p0.y}, ${cx} ${p1.y}, ${p1.x} ${p1.y}`;
    }
    const last = coords[coords.length - 1] || firstCoord;
    const areaPath = `${dPath} L ${last.x} ${h - padY} L ${firstCoord.x} ${h - padY} Z`;

    const nowIdx = opts.currentIndex ?? coords.length - 1;
    const nowPt = coords[Math.max(0, Math.min(coords.length - 1, nowIdx))] || firstCoord;
    const strokeVar = opts.tone === "energy" ? "var(--lvx-energy)" : opts.tone === "success" ? "var(--lvx-success)" : "var(--lvx-brand)";
    const gradId = `lvx-spk-grad-${opts.tone || "brand"}-${++lvxSparklineSeq}`;

    const gridLines = [0.2, 0.5, 0.8].map(r => {
        const gy = Math.round(padY + innerH * r);
        return `<line class="lvx-sparkline__grid" x1="${padX}" y1="${gy}" x2="${w - padX}" y2="${gy}"/>`;
    }).join("");

    const dotsSvg = coords.map((pt, idx) => {
        const isNow = idx === nowIdx;
        return `<circle class="lvx-sparkline__dot${isNow ? " lvx-sparkline__dot--now" : ""}" cx="${pt.x}" cy="${pt.y}" r="${isNow ? 4.5 : 3}" data-value="${pt.v}"/>`;
    }).join("");

    const svgHtml = `<svg class="lvx-sparkline__svg" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${opts.ariaLabel || "趋势图表"}">
        <defs>
            <linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" style="stop-color:${strokeVar}" stop-opacity="0.24"/>
                <stop offset="100%" style="stop-color:${strokeVar}" stop-opacity="0.0"/>
            </linearGradient>
        </defs>
        ${gridLines}
        <line class="lvx-sparkline__now" x1="${nowPt.x}" y1="${padY - 4}" x2="${nowPt.x}" y2="${h - padY + 4}"/>
        <path class="lvx-sparkline__area" d="${areaPath}" fill="url(#${gradId})"/>
        <path class="lvx-sparkline__line" d="${dPath}"/>
        ${dotsSvg}
    </svg>`;

    const wrap = lvxH("div", {
        class: `lvx-sparkline${opts.tone && opts.tone !== "brand" ? ` lvx-sparkline--${opts.tone}` : ""}`,
        role: "figure",
        ariaLabel: opts.ariaLabel || "趋势图表",
        html: svgHtml,
    });

    if (opts.labels?.length) {
        const labelRow = lvxH("div", { class: "lvx-sparkline__labels" });
        for (const lb of opts.labels) labelRow.appendChild(lvxH("span", { text: lb }));
        wrap.appendChild(labelRow);
    }
    if (opts.showSummary) {
        const u = opts.unit || "";
        const avg = Math.round((pts.reduce((a, b) => a + b, 0) / pts.length) * 10) / 10;
        const summary = lvxH("div", { class: "lvx-sparkline__summary" },
            lvxH("span", { text: `峰值 ${Math.max(...pts)}${u}` }),
            lvxH("span", { text: `均值 ${avg}${u}` }),
            lvxH("span", { text: `当前 ${nowPt.v}${u}` }),
        );
        wrap.appendChild(summary);
    }
    return wrap;
}

export interface LvxCommandItem {
    id: string;
    label: string;
    group?: string;
    icon?: string;
    shortcut?: string[];
    onSelect?: () => void;
}

/** 命令面板（即时搜索过滤 + 分组列表 + 键盘上下导航 + Kbd 快捷键展示） */
export function lvxCommandPalette(opts: {
    items: LvxCommandItem[];
    placeholder?: string;
    ariaLabel?: string;
    onSelect?: (id: string) => void;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-cmdp", role: "dialog", ariaLabel: opts.ariaLabel || "命令面板" });
    const input = lvxH("input", {
        type: "text",
        class: "lvx-cmdp__input",
        placeholder: opts.placeholder || "输入命令或搜索功能...",
        ariaLabel: "搜索命令",
    }) as HTMLInputElement;
    const bar = lvxH("div", { class: "lvx-cmdp__bar" },
        lvxH("span", { text: "⌕", style: { fontSize: "15px", color: "var(--lvx-brand)" } }),
        input,
        lvxKbd("ESC"),
    );
    const list = lvxH("div", { class: "lvx-cmdp__list", role: "listbox" });
    let activeIdx = 0;
    let currentBtns: Array<{ btn: HTMLButtonElement; item: LvxCommandItem }> = [];

    const renderList = (query = "") => {
        list.innerHTML = "";
        currentBtns = [];
        const q = query.trim().toLowerCase();
        const filtered = opts.items.filter(it => !q || it.label.toLowerCase().includes(q) || (it.group || "").toLowerCase().includes(q));
        let lastGroup = "";
        filtered.forEach((it, idx) => {
            if (it.group && it.group !== lastGroup) {
                lastGroup = it.group;
                list.appendChild(lvxH("div", { class: "lvx-cmdp__group", text: it.group }));
            }
            const left = lvxH("span", { style: { display: "inline-flex", alignItems: "center", gap: "8px" } },
                it.icon ? lvxH("span", { text: it.icon }) : null,
                lvxH("span", { text: it.label }),
            );
            const btn = lvxH("button", {
                type: "button",
                class: "lvx-cmdp__item",
                role: "option",
                "aria-selected": idx === 0 ? "true" : "false",
                onclick: () => {
                    currentBtns.forEach(entry => entry.btn.setAttribute("aria-selected", entry.btn === btn ? "true" : "false"));
                    it.onSelect?.();
                    opts.onSelect?.(it.id);
                },
            }, left, it.shortcut?.length ? lvxKbd(it.shortcut) : null);
            currentBtns.push({ btn, item: it });
            list.appendChild(btn);
        });
        activeIdx = 0;
    };

    input.addEventListener("input", () => renderList(input.value));
    input.addEventListener("keydown", (ev: KeyboardEvent) => {
        if (!currentBtns.length) return;
        if (ev.key === "ArrowDown") {
            ev.preventDefault?.();
            activeIdx = (activeIdx + 1) % currentBtns.length;
            currentBtns.forEach((e, i) => e.btn.setAttribute("aria-selected", i === activeIdx ? "true" : "false"));
        } else if (ev.key === "ArrowUp") {
            ev.preventDefault?.();
            activeIdx = (activeIdx - 1 + currentBtns.length) % currentBtns.length;
            currentBtns.forEach((e, i) => e.btn.setAttribute("aria-selected", i === activeIdx ? "true" : "false"));
        } else if (ev.key === "Enter") {
            ev.preventDefault?.();
            const target = currentBtns[activeIdx];
            if (target) {
                target.item.onSelect?.();
                opts.onSelect?.(target.item.id);
            }
        }
    });

    renderList();
    root.appendChild(bar);
    root.appendChild(list);
    return root;
}

export interface LvxTourStep { title: string; desc: string; badge?: string }

/** 新手引导聚光灯卡（多步切换 + 进度胶囊点 + 完成回调） */
export function lvxTour(opts: {
    steps: LvxTourStep[];
    current?: number;
    mascot?: string;
    ariaLabel?: string;
    onChange?: (stepIdx: number) => void;
    onFinish?: () => void;
}): HTMLDivElement {
    const steps = opts.steps.length ? opts.steps : [{ title: "欢迎", desc: "" }];
    let cur = Math.max(0, Math.min(steps.length - 1, opts.current ?? 0));

    const badgeEl = lvxChip({ text: "", tone: "brand" });
    const titleEl = lvxH("div", { class: "lvx-tour__title", text: "" });
    const descEl = lvxH("div", { class: "lvx-tour__desc", text: "" });
    const dotsWrap = lvxH("div", { class: "lvx-tour__dots" });
    const dots: HTMLSpanElement[] = steps.map(() => {
        const d = lvxH("span", { class: "lvx-tour__dot" });
        dotsWrap.appendChild(d);
        return d;
    });

    const prevBtn = lvxButton({ label: "上一步", sm: true });
    const nextBtn = lvxButton({ label: "下一步", variant: "primary", sm: true });

    const sync = () => {
        const st = steps[cur] || { title: "", desc: "", badge: undefined };
        badgeEl.textContent = st.badge || `步骤 ${cur + 1} / ${steps.length}`;
        titleEl.textContent = st.title;
        descEl.textContent = st.desc;
        dots.forEach((d, idx) => { d.setAttribute("aria-current", idx === cur ? "step" : "false"); d.parentElement?.setAttribute("aria-hidden", "true"); });
        prevBtn.disabled = cur === 0;
        nextBtn.textContent = cur === steps.length - 1 ? "完成引导" : "下一步";
    };

    prevBtn.addEventListener("click", () => {
        if (cur > 0) {
            cur--;
            sync();
            opts.onChange?.(cur);
        }
    });
    nextBtn.addEventListener("click", () => {
        if (cur < steps.length - 1) {
            cur++;
            sync();
            opts.onChange?.(cur);
        } else {
            opts.onFinish?.();
        }
    });

    sync();
    return lvxH("div", { class: "lvx-tour", role: "dialog", ariaLabel: opts.ariaLabel || "功能引导" },
        lvxH("div", { class: "lvx-tour__head" }, badgeEl, opts.mascot ? lvxH("span", { html: opts.mascot }) : null),
        titleEl,
        descEl,
        lvxH("div", { class: "lvx-tour__foot" }, dotsWrap, lvxH("div", { style: { display: "flex", gap: "6px" } }, prevBtn, nextBtn)),
    );
}

/** 虚拟滚动列表（真实按 scrollTop 切片渲染可见窗口，支持万级长列表丝滑滚动） */
export function lvxVirtualList<T>(opts: {
    items: T[];
    itemHeight?: number;
    height?: number;
    overscan?: number;
    renderItem: (item: T, index: number) => HTMLElement | string;
    ariaLabel?: string;
}): HTMLDivElement {
    const rowH = opts.itemHeight ?? 40;
    const viewH = opts.height ?? 200;
    const overscan = opts.overscan ?? 2;
    const totalH = opts.items.length * rowH;

    const root = lvxH("div", {
        class: "lvx-vlist",
        role: "list",
        tabIndex: 0,
        ariaLabel: opts.ariaLabel || "虚拟列表",
        style: { height: `${viewH}px` },
    });
    const spacer = lvxH("div", { class: "lvx-vlist__spacer", style: { height: `${totalH}px` } });
    const viewport = lvxH("div", { class: "lvx-vlist__viewport" });
    spacer.appendChild(viewport);
    root.appendChild(spacer);

    const renderWindow = (scrollTop = 0) => {
        viewport.innerHTML = "";
        const startIdx = Math.max(0, Math.floor(scrollTop / rowH) - overscan);
        const visibleCount = Math.ceil(viewH / rowH) + overscan * 2;
        const endIdx = Math.min(opts.items.length, startIdx + visibleCount);
        viewport.style.transform = `translateY(${startIdx * rowH}px)`;
        for (let i = startIdx; i < endIdx; i++) {
            const itm = opts.items[i];
            if (itm === undefined) continue;
            const content = opts.renderItem(itm, i);
            const row = lvxH("div", {
                class: "lvx-vlist__row",
                role: "listitem",
                "data-vlist-index": String(i),
                style: { height: `${rowH}px` },
            });
            if (typeof content === "string") row.textContent = content;
            else row.appendChild(content);
            viewport.appendChild(row);
        }
    };

    root.addEventListener("scroll", () => renderWindow((root as any).scrollTop || 0));
    renderWindow(0);
    return root;
}

export interface LvxDragSortItem { id: string; label: string; meta?: string }

/** 拖拽排序列表（支持 HTML5 拖拽重排 + 按钮/键盘上下移动无障碍重排） */
export function lvxDragSort(opts: {
    items: LvxDragSortItem[];
    ariaLabel?: string;
    onReorder?: (ids: string[]) => void;
}): HTMLDivElement {
    const list = opts.items.map(it => ({ ...it }));
    const root = lvxH("div", { class: "lvx-dragsort", role: "list", ariaLabel: opts.ariaLabel || "可排序列表" });
    let dragFromIdx = -1;

    const moveItem = (from: number, to: number) => {
        if (from === to || from < 0 || to < 0 || from >= list.length || to >= list.length) return;
        const moved = list[from];
        if (!moved) return;
        list.splice(from, 1);
        list.splice(to, 0, moved);
        render();
        opts.onReorder?.(list.map(x => x.id));
    };

    const render = () => {
        root.innerHTML = "";
        list.forEach((it, idx) => {
            const upBtn = lvxButton({ label: "↑", sm: true, ariaLabel: "上移", disabled: idx === 0, onClick: () => moveItem(idx, idx - 1) });
            const downBtn = lvxButton({ label: "↓", sm: true, ariaLabel: "下移", disabled: idx === list.length - 1, onClick: () => moveItem(idx, idx + 1) });
            const row = lvxH("div", {
                class: "lvx-dragsort__item",
                role: "listitem",
                draggable: "true",
                "data-sort-id": it.id,
            },
                lvxH("span", { class: "lvx-dragsort__handle", text: "⋮⋮", "aria-hidden": "true" }),
                lvxH("span", { class: "lvx-dragsort__label", text: it.label }),
                it.meta ? lvxTag(it.meta) : null,
                lvxH("span", { class: "lvx-dragsort__actions" }, upBtn, downBtn),
            );
            row.addEventListener("dragstart", () => { dragFromIdx = idx; row.classList.add("is-dragging"); });
            row.addEventListener("dragend", () => { dragFromIdx = -1; row.classList.remove("is-dragging"); });
            row.addEventListener("dragover", (e: Event) => { e.preventDefault?.(); });
            row.addEventListener("drop", (e: Event) => {
                e.preventDefault?.();
                if (dragFromIdx >= 0 && dragFromIdx !== idx) moveItem(dragFromIdx, idx);
            });
            root.appendChild(row);
        });
    };

    render();
    return root;
}

/** 智能图片卡片（懒加载 + 点击缩放预览 + 底部图注） */
export function lvxImage(opts: {
    src: string;
    alt?: string;
    caption?: string;
    width?: number | string;
    height?: number | string;
    preview?: boolean;
}): HTMLElement {
    const style: Record<string, string> = {};
    if (opts.width !== undefined) style.width = typeof opts.width === "number" ? `${opts.width}px` : opts.width;
    if (opts.height !== undefined) style.height = typeof opts.height === "number" ? `${opts.height}px` : opts.height;
    const fig = lvxH("figure", { class: "lvx-image", "data-zoomed": "false", style });
    const img = lvxH("img", {
        class: "lvx-image__img",
        src: opts.src,
        alt: opts.alt || opts.caption || "",
        loading: "lazy",
        tabIndex: 0,
        role: "button",
    });
    if (opts.preview !== false) {
        img.addEventListener("click", () => {
            const z = fig.getAttribute("data-zoomed") === "true";
            fig.setAttribute("data-zoomed", z ? "false" : "true");
        });
        img.addEventListener("keydown", (ev: KeyboardEvent) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); img.click(); } });
    }
    fig.appendChild(img);
    if (opts.caption) {
        fig.appendChild(lvxH("figcaption", { class: "lvx-image__caption", text: opts.caption }));
    }
    return fig;
}

const CONFETTI_COLORS = ["var(--lvx-brand)", "var(--lvx-energy)", "var(--lvx-success)", "var(--lvx-danger)", "var(--lvx-brand-soft)"];

/** 在指定容器内发射一次庆祝彩屑（严格受 data-lv-celebration & data-lv-motion 门控） */
export function triggerLvConfetti(host: HTMLElement, count = 14): number {
    if (typeof document !== "undefined") {
        const root = document.documentElement;
        if (root?.getAttribute("data-lv-celebration") === "off" || root?.getAttribute("data-lv-motion") === "off" || root?.getAttribute("data-lv-motion") === "minimal") {
            return 0;
        }
    }
    host.innerHTML = "";
    for (let i = 0; i < count; i++) {
        const angle = (Math.PI * 2 * i) / count;
        const dist = 26 + (i % 3) * 14;
        const tx = Math.round(Math.cos(angle) * dist);
        const ty = Math.round(Math.sin(angle) * dist - 14);
        const rot = (i * 55) % 360;
        const piece = lvxH("span", {
            class: "lvx-confetti__piece",
            "aria-hidden": "true",
            style: { background: CONFETTI_COLORS[i % CONFETTI_COLORS.length] },
        });
        if (typeof piece.style?.setProperty === "function") {
            piece.style.setProperty("--tx", `${tx}px`);
            piece.style.setProperty("--ty", `${ty}px`);
            piece.style.setProperty("--rot", `${rot}deg`);
        }
        host.appendChild(piece);
    }
    return count;
}

/** 庆祝撒花组件容器（初始化即生成一套受偏好门控的彩屑节点） */
export function lvxConfetti(opts?: { count?: number; ariaLabel?: string }): HTMLDivElement {
    const wrap = lvxH("div", { class: "lvx-confetti", ariaLabel: opts?.ariaLabel || "庆祝特效" });
    triggerLvConfetti(wrap, opts?.count ?? 12);
    return wrap;
}

export interface LvxSwipeActionButton {
    label: string;
    tone?: "brand" | "energy" | "danger";
    onClick?: () => void;
}

/** 手势左滑操作行（Touch/Gesture；支持左滑展开/收起隐藏胶囊按钮） */
export function lvxSwipeAction(opts: {
    title: string;
    desc?: string;
    prefix?: string;
    actions: LvxSwipeActionButton[];
    ariaLabel?: string;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-swipe", "data-revealed": "false", role: "group", ariaLabel: opts.ariaLabel || opts.title });
    const actionsBar = lvxH("div", { class: "lvx-swipe__actions" });

    for (const act of opts.actions) {
        const variant = act.tone === "danger" ? "danger" : act.tone === "energy" ? "energy" : "primary";
        const btn = lvxButton({
            label: act.label,
            variant,
            sm: true,
            onClick: () => {
                root.setAttribute("data-revealed", "false");
                toggleBtn.textContent = "操作 ◂";
                act.onClick?.();
            },
        });
        actionsBar.appendChild(btn);
    }

    const toggleBtn = lvxButton({
        label: "操作 ◂",
        sm: true,
        variant: "ghost",
        onClick: () => {
            const rev = root.getAttribute("data-revealed") === "true";
            root.setAttribute("data-revealed", rev ? "false" : "true");
            toggleBtn.textContent = rev ? "操作 ◂" : "收起 ▸";
        },
    });

    const front = lvxH("div", { class: "lvx-swipe__front" },
        lvxH("div", { style: { display: "flex", alignItems: "center", gap: "10px", minWidth: "0" } },
            opts.prefix ? lvxH("span", { text: opts.prefix, style: { fontSize: "18px" } }) : null,
            lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "2px", minWidth: "0" } },
                lvxH("span", { text: opts.title, style: { fontWeight: "600", fontSize: "13px" } }),
                opts.desc ? lvxH("span", { text: opts.desc, style: { fontSize: "12px", color: "var(--lvx-text-muted)" } }) : null,
            ),
        ),
        toggleBtn,
    );

    let startX = 0;
    front.addEventListener("pointerdown", (e: any) => { startX = e.clientX ?? 0; });
    front.addEventListener("pointerup", (e: any) => {
        const dx = (e.clientX ?? 0) - startX;
        if (dx < -30) {
            root.setAttribute("data-revealed", "true");
            toggleBtn.textContent = "收起 ▸";
        } else if (dx > 30) {
            root.setAttribute("data-revealed", "false");
            toggleBtn.textContent = "操作 ◂";
        }
    });

    root.appendChild(actionsBar);
    root.appendChild(front);
    return root;
}

