/** 73. 跨插件今日动态流与 8 仓联合灾备快照卡 ActivityStream */
export function lvxActivityStream(opts: {
    records: Array<{ plugin: string; time: string; action: string; detail?: string; tone?: LvxTone }>;
    backupStatus?: string;
    onExportBackup?: () => void;
    onAppendDiary?: () => void;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-actstream", role: "region", ariaLabel: "跨插件今日动态流" });
    const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px" } },
            lvxH("strong", { style: { fontSize: "14px" }, text: "🌊 全生态今日动态流 (lvActivity)" }),
            opts.backupStatus ? lvxChip({ text: opts.backupStatus, tone: "success", size: "sm" }) : null,
        ),
        lvxH("div", { style: { display: "inline-flex", gap: "6px", flexWrap: "wrap" } },
            opts.onExportBackup ? lvxButton({ label: "📦 8仓联合备份", sm: true, onClick: opts.onExportBackup }) : null,
            opts.onAppendDiary ? lvxButton({ label: "📝 汇总入今日日记", variant: "primary", sm: true, onClick: opts.onAppendDiary }) : null,
        ),
    );
    root.appendChild(head);
    const list = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px" } });
    for (const r of opts.records) {
        const row = lvxH("div", {
            style: {
                display: "flex", alignItems: "center", justifyContent: "space-between", gap: "8px", flexWrap: "wrap",
                padding: "8px 12px", borderRadius: "10px", background: "var(--lvx-surface-sunken)",
                border: "1px solid var(--lvx-border)", fontSize: "13px",
            },
        },
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "6px 8px", minWidth: "0", flexWrap: "wrap", flex: "1" } },
                lvxChip({ text: r.plugin, tone: r.tone || "brand", size: "sm" }),
                lvxH("strong", { style: { minWidth: "0" }, text: r.action }),
                r.detail ? lvxH("span", { style: { color: "var(--lvx-text-muted)", fontSize: "12px", minWidth: "0" }, text: `· ${r.detail}` }) : null,
            ),
            lvxTag({ text: r.time, size: "sm" }),
        );
        list.appendChild(row);
    }
    root.appendChild(list);
    return root;
}

/** 74. 四级渐进降噪跨插件通知横幅与免扰胶囊 ToastCard */
export function lvxToastCard(opts: {
    plugin: string;
    level?: "L1" | "L2" | "L3" | "L4";
    title: string;
    message: string;
    snoozeOptions?: string[];
    onAction?: () => void;
    onSnooze?: (opt: string) => void;
    onDismiss?: () => void;
}): HTMLDivElement {
    const levelColor = opts.level === "L4" ? "var(--lvx-danger)" : opts.level === "L3" ? "var(--lvx-warn)" : opts.level === "L2" ? "var(--lvx-energy)" : "var(--lvx-brand)";
    const root = lvxH("div", { class: "lvx-toast", role: "status", ariaLabel: opts.title, style: { borderLeftColor: levelColor } });
    const top = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px", width: "100%" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "6px", flex: "1 1 200px", minWidth: "0", flexWrap: "wrap" } },
            lvxChip({ text: opts.plugin, tone: "brand", size: "sm" }),
            lvxTag({ text: `${opts.level || "L2"} · 渐进降噪`, tone: "energy", size: "sm" }),
            lvxH("strong", { style: { fontSize: "14px", minWidth: "0", wordBreak: "break-word" }, text: opts.title }),
        ),
        opts.onDismiss ? lvxIconButton({ icon: "✕", label: "关闭通知", sm: true, variant: "ghost", onClick: opts.onDismiss }) : null,
    );
    const msg = lvxH("div", { style: { fontSize: "13px", color: "var(--lvx-text-muted)" }, text: opts.message });
    const snoozeRow = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } });
    const snWrap = lvxH("div", { style: { display: "inline-flex", gap: "6px", flexWrap: "wrap" } });
    for (const s of opts.snoozeOptions || ["⏳ 延后 1h", "🌙 今日分类免扰"]) {
        snWrap.appendChild(lvxChip({ text: s, tone: "neutral", size: "sm", interactive: true, onClick: () => opts.onSnooze?.(s) }));
    }
    snoozeRow.appendChild(snWrap);
    if (opts.onAction) {
        snoozeRow.appendChild(lvxButton({ label: "立即处理 ›", variant: "primary", sm: true, onClick: opts.onAction }));
    }
    root.appendChild(top);
    root.appendChild(msg);
    root.appendChild(snoozeRow);
    return root;
}

/** 75. 块助手胶囊触发器与自适应块操作中心 BlockActionCard */
export function lvxBlockActionCard(opts: {
    blockType: string;
    blockId: string;
    excerpt: string;
    mode?: "focus" | "command";
    actions: Array<{ id: string; label: string; plugin: string; icon: string; tone?: LvxTone }>;
    onTrigger?: (id: string) => void;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-bact", role: "region", ariaLabel: "小驴块动作中心" });
    const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", flexWrap: "wrap", gap: "6px" } },
            lvxChip({ text: `⚡ 块动作胶囊 · ${opts.blockType}`, tone: "brand", size: "sm" }),
            lvxTag({ text: `ID: ${opts.blockId}`, size: "sm" }),
        ),
        lvxTag({ text: opts.mode === "command" ? "Command 全量面板" : "Focus 极简密度 (0.5ms)", tone: "success", size: "sm" }),
    );
    const quote = lvxH("div", {
        style: {
            padding: "8px 12px", borderRadius: "8px", background: "var(--lvx-surface-sunken)",
            border: "1px solid var(--lvx-border)", fontSize: "12px", color: "var(--lvx-text-muted)",
        },
        text: opts.excerpt,
    });
    const grid = lvxH("div", { style: { display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(175px,1fr))", gap: "8px" } });
    for (const act of opts.actions) {
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-list-item lvx-list-item--interactive",
            style: { padding: "8px 12px", justifyContent: "space-between" },
            onclick: () => opts.onTrigger?.(act.id),
        },
            lvxH("span", { style: { display: "inline-flex", alignItems: "center", gap: "6px", fontWeight: "600", fontSize: "13px" } },
                lvxH("span", { text: act.icon }),
                lvxH("span", { text: act.label }),
            ),
            lvxTag({ text: act.plugin, tone: act.tone || "brand", size: "sm" }),
        );
        grid.appendChild(btn);
    }
    root.appendChild(head);
    root.appendChild(quote);
    root.appendChild(grid);
    return root;
}

/** 76. 阶梯渐进揭晓列表卡（R55）SequenceCard */
export function lvxSequenceCard(opts: {
    title: string;
    steps: string[];
    revealedCount?: number;
    onStepChange?: (revealed: number) => void;
}): HTMLDivElement {
    let rev = Math.max(0, Math.min(opts.steps.length, opts.revealedCount ?? 1));
    const root = lvxH("div", { class: "lvx-seqcard", role: "region", ariaLabel: opts.title });
    const list = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px" } });
    const statusChip = lvxChip({ text: "", tone: "brand", size: "sm" });

    const render = () => {
        list.innerHTML = "";
        statusChip.textContent = `已揭晓 ${rev}/${opts.steps.length} 阶`;
        opts.steps.forEach((st, idx) => {
            const isRev = idx < rev;
            const row = lvxH("button", {
                type: "button",
                class: "lvx-seqcard__row",
                "data-revealed": isRev ? "true" : "false", "aria-expanded": isRev ? "true" : "false",
                onclick: () => {
                    rev = idx + 1;
                    render();
                    opts.onStepChange?.(rev);
                },
            },
                lvxBadge({ text: String(idx + 1), tone: isRev ? "success" : "neutral" }),
                lvxH("span", {
                    style: { flex: "1", textAlign: "left", fontWeight: isRev ? "600" : "500", color: isRev ? "var(--lvx-text)" : "var(--lvx-text-muted)" },
                    text: isRev ? st : `🔒 阶梯 #${idx + 1} 待回忆（点击或按 Space 逐级揭晓）`,
                }),
            );
            list.appendChild(row);
        });
    };

    const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px", width: "100%" } },
        lvxH("strong", { style: { fontSize: "14px", minWidth: "0", flex: "1 1 160px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }, text: `🪜 ${opts.title}` }),
        statusChip,
    );
    const foot = lvxH("div", { style: { display: "flex", gap: "8px", flexWrap: "wrap", justifyContent: "flex-end" } },
        lvxButton({
            label: "揭晓下一阶 [Space]",
            variant: "primary",
            sm: true,
            onClick: () => {
                rev = rev < opts.steps.length ? rev + 1 : 0;
                render();
                opts.onStepChange?.(rev);
            },
        }),
        lvxButton({
            label: "全部揭晓",
            sm: true,
            onClick: () => {
                rev = opts.steps.length;
                render();
                opts.onStepChange?.(rev);
            },
        }),
    );
    render();
    root.appendChild(head);
    root.appendChild(list);
    root.appendChild(foot);
    return root;
}

/** 77. FSRS-5 四档间隔重复评分栏 FsrsRatingBar */
export function lvxFsrsRatingBar(opts?: {
    ratings?: Array<{ grade: 1 | 2 | 3 | 4; label: string; interval: string; key: string; stabilityDelta?: string }>;
    retention?: string;
    onRate?: (grade: number) => void;
}): HTMLDivElement {
    const items = opts?.ratings || [
        { grade: 1 as const, label: "重来 Again", interval: "10 分钟", key: "1", stabilityDelta: "S → 1.2d" },
        { grade: 2 as const, label: "困难 Hard", interval: "3 天", key: "2", stabilityDelta: "S → 6.8d" },
        { grade: 3 as const, label: "良好 Good", interval: "14 天", key: "3", stabilityDelta: "S → 18.4d" },
        { grade: 4 as const, label: "简单 Easy", interval: "32 天", key: "4", stabilityDelta: "S → 42.0d" },
    ];
    const borderColors: Record<number, string> = {
        1: "var(--lvx-danger)",
        2: "var(--lvx-warn)",
        3: "var(--lvx-brand)",
        4: "var(--lvx-success)",
    };
    const wrap = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "8px", width: "100%" } });
    const bar = lvxH("div", { class: "lvx-fsrsbar", role: "group", ariaLabel: "FSRS 四档评分栏", style: { containerType: "inline-size" } });
    for (const it of items) {
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-fsrsbar__btn",
            style: { borderTopColor: borderColors[it.grade] || "var(--lvx-brand)" },
            onclick: () => opts?.onRate?.(it.grade),
        },
            lvxH("span", { style: { fontSize: "12px", fontWeight: "700", color: "var(--lvx-text-muted)" }, text: `⏱ ${it.interval}` }),
            lvxH("strong", { style: { fontSize: "13px", whiteSpace: "nowrap" }, text: it.label }),
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "4px", marginTop: "2px" } },
                lvxKbd(it.key),
                it.stabilityDelta ? lvxH("span", { style: { fontSize: "11px", color: "var(--lvx-text-muted)" }, text: it.stabilityDelta }) : null,
            ),
        );
        bar.appendChild(btn);
    }
    wrap.appendChild(bar);
    if (opts?.retention) {
        wrap.appendChild(lvxH("div", { style: { fontSize: "12px", color: "var(--lvx-text-muted)", textAlign: "right" }, text: opts.retention }));
    }
    return wrap;
}

/** 78. 卡包分级树与新学/学习/复习三色到期计数行 DeckTreeCard */
export function lvxDeckTreeCard(opts: {
    decks: Array<{ id: string; name: string; depth?: number; newCount: number; learnCount: number; reviewCount: number; retention?: string }>;
    onStudy?: (id: string) => void;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-decktree", role: "region", ariaLabel: "闪卡牌组树" });
    for (const d of opts.decks) {
        const row = lvxH("div", {
            style: {
                display: "flex", alignItems: "center", justifyContent: "space-between", gap: "10px", flexWrap: "wrap",
                padding: "8px 12px", paddingLeft: `${12 + (d.depth || 0) * 18}px`,
                borderRadius: "10px", background: d.depth ? "var(--lvx-surface-sunken)" : "var(--lvx-surface)",
                border: "1px solid var(--lvx-border)",
            },
        },
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "6px 8px", minWidth: "0", flex: "1 1 120px", flexWrap: "wrap" } },
                lvxH("span", { text: d.depth ? "↳ 🗂" : "📚" }),
                lvxH("strong", { style: { fontSize: "13px", minWidth: "0" }, text: d.name }),
                d.retention ? lvxTag({ text: `留存 ${d.retention}`, size: "sm" }) : null,
            ),
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "6px", flexWrap: "wrap" } },
                lvxChip({ text: `新 ${d.newCount}`, tone: "brand", size: "sm" }),
                lvxChip({ text: `学 ${d.learnCount}`, tone: "energy", size: "sm" }),
                lvxChip({ text: `复 ${d.reviewCount}`, tone: "success", size: "sm" }),
                lvxButton({ label: "复习", variant: "primary", sm: true, onClick: () => opts.onStudy?.(d.id) }),
            ),
        );
        root.appendChild(row);
    }
    return root;
}

/** 79. 专注番茄钟倒计时环与顶栏药丸微条（支持顶栏横条 Strip / 1×1 方卡 / 2×1 宽卡三比例切换） PomodoroTimer */
export function lvxPomodoroTimer(opts: {
    habitName: string;
    presets?: number[];
    initialMinutes?: number;
    whiteNoise?: string;
    ratio?: "strip" | "1x1" | "2x1";
    onStateChange?: (running: boolean, minutes: number) => void;
}): HTMLDivElement {
    let mins = opts.initialMinutes ?? 25;
    let running = true;
    let curRatio: "strip" | "1x1" | "2x1" = opts.ratio || "2x1";
    const root = lvxH("div", { class: "lvx-pomo", role: "region", ariaLabel: "番茄专注计时器" });

    const render = () => {
        root.innerHTML = "";
        root.className = `lvx-pomo${curRatio === "1x1" ? " lvx-ratio--1x1" : ""}`;

        const headBar = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", gap: "8px", flexWrap: "wrap" } },
            lvxH("strong", { style: { fontSize: "13px" }, text: `🍅 番茄专注 · ${opts.habitName}` }),
            lvxSegmented({
                size: "sm",
                options: [
                    { value: "strip", label: "顶栏微条" },
                    { value: "1x1", label: "1×1 窄卡" },
                    { value: "2x1", label: "2×1 宽卡" },
                ],
                value: curRatio,
                onChange: v => { curRatio = v as any; render(); },
            }),
        );
        root.appendChild(headBar);

        if (curRatio === "strip") {
            const stripEl = lvxH("div", {
                class: "lvx-ratio--strip",
                style: { background: "var(--lvx-ink)", color: "var(--lvx-ink-text)", fontSize: "12px" },
            },
                lvxH("span", { text: "🍅 顶栏微条 · " }, lvxH("strong", { text: opts.habitName })),
                lvxH("span", { style: { color: "var(--lvx-energy)", fontFamily: "var(--lvx-font-num)", fontWeight: "700" }, text: `${running ? "专注中" : "已暂停"} ${mins}:00` }),
                lvxButton({ label: running ? "⏸" : "▶", sm: true, variant: "energy", onClick: () => { running = !running; render(); opts.onStateChange?.(running, mins); } }),
            );
            root.appendChild(stripEl);
            return;
        }

        const ringHost = lvxH("div", { style: { display: "flex", flexDirection: curRatio === "1x1" ? "column" : "row", alignItems: "center", justifyContent: "space-between", gap: "12px", flexWrap: "wrap" } });
        ringHost.appendChild(lvxProgressRing({ value: running ? 0.76 : 0.4, size: curRatio === "1x1" ? "md" : "lg", tone: "energy", label: `${mins}:00`, sublabel: running ? "心流计时" : "已暂停" }));
        const right = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "8px", flex: "1", minWidth: curRatio === "1x1" ? "100%" : "180px" } },
            lvxH("div", { style: { display: "flex", gap: "6px", flexWrap: "wrap" } },
                ...(opts.presets || [25, 45, 60]).map(p => lvxChip({
                    text: `${p}m`,
                    tone: p === mins ? "energy" : "neutral",
                    size: "sm",
                    interactive: true,
                    onClick: () => { mins = p; render(); opts.onStateChange?.(running, mins); },
                })),
                opts.whiteNoise && curRatio !== "1x1" ? lvxTag({ text: `🎧 ${opts.whiteNoise}`, tone: "brand", size: "sm" }) : null,
            ),
            lvxH("div", { style: { display: "flex", gap: "8px", flexWrap: "wrap" } },
                lvxButton({
                    label: running ? "⏸ 暂停" : "▶ 继续",
                    variant: running ? "default" : "primary",
                    sm: true,
                    onClick: () => { running = !running; render(); opts.onStateChange?.(running, mins); },
                }),
                lvxButton({ label: "✓ 结算打卡", variant: "energy", sm: true, onClick: () => opts.onStateChange?.(false, mins) }),
            ),
        );
        ringHost.appendChild(right);
        root.appendChild(ringHost);
    };
    render();
    return root;
}

/** 80. 连击救赎补卡券与断签修复礼券卡 StreakRepairCard */
export function lvxStreakRepairCard(opts: {
    habitName: string;
    missedDate: string;
    streakDays: number;
    ticketsLeft: number;
    ticketsMax?: number;
    onRedeem?: () => void;
}): HTMLDivElement {
    let left = opts.ticketsLeft;
    let redeemed = false;
    const root = lvxH("div", { class: "lvx-ticket", role: "region", ariaLabel: "连击救赎补卡券" });
    const render = () => {
        root.innerHTML = "";
        const main = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "4px", flex: "1", minWidth: "200px" } },
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "6px" } },
                lvxChip({ text: "🎫 自律免死金牌 / 补卡礼券", tone: "energy", size: "sm" }),
                lvxTag({ text: `本月额度 ${left}/${opts.ticketsMax ?? 2} 张`, tone: "brand", size: "sm" }),
            ),
            lvxH("strong", { style: { fontSize: "14px" }, text: redeemed ? `✓ 已成功救赎「${opts.habitName}」(${opts.streakDays} 天连击已无缝接续)` : `昨日 (${opts.missedDate})「${opts.habitName}」漏签 · 待救赎 ${opts.streakDays} 天连击` }),
            lvxH("span", { style: { fontSize: "12px", color: "var(--lvx-text-muted)" }, text: "启用补卡券后连胜纪录不断档，心流韧性指数按 EMA 80% 柔性保留。" }),
        );
        const stub = lvxH("div", { class: "lvx-ticket__stub" },
            lvxButton({
                label: redeemed ? "✓ 已核销礼券" : "🛡️ 立即核销救赎",
                variant: redeemed ? "default" : "energy",
                sm: true,
                disabled: redeemed || left <= 0,
                onClick: () => {
                    if (redeemed || left <= 0) return;
                    redeemed = true;
                    left--;
                    render();
                    opts.onRedeem?.();
                },
            }),
        );
        root.appendChild(main);
        root.appendChild(stub);
    };
    render();
    return root;
}

/** 81. 五维成就勋章解锁墙 AchievementWall */
export function lvxAchievementWall(opts: {
    badges: Array<{ id: string; icon: string; name: string; category: string; progress: string; unlocked: boolean }>;
    onSelectBadge?: (id: string) => void;
}): HTMLDivElement {
    const grid = lvxH("div", { class: "lvx-medalwall", role: "region", ariaLabel: "五维成就勋章墙" });
    for (const b of opts.badges) {
        const card = lvxH("button", {
            type: "button",
            class: "lvx-medal",
            "data-unlocked": b.unlocked ? "true" : "false",
            onclick: () => opts.onSelectBadge?.(b.id),
        },
            lvxH("span", { style: { fontSize: "26px" }, text: b.icon }),
            lvxH("strong", { style: { fontSize: "13px" }, text: b.name }),
            lvxTag({ text: b.category, tone: b.unlocked ? "energy" : "neutral", size: "sm" }),
            lvxH("span", { style: { fontSize: "11px", color: "var(--lvx-text-muted)" }, text: b.progress }),
        );
        grid.appendChild(card);
    }
    return grid;
}

/** 82. 管家仿生 Bento 倒数日与黄历天气组合卡（支持 1×1 单卡 / 2×1 双栏组合 / Strip 横条三比例） BentoCountdownCard */
export function lvxBentoCountdownCard(opts: {
    eventTitle: string;
    daysLeft: number;
    targetDate: string;
    lunarText: string;
    solarTerm: string;
    weatherText: string;
    lifeIndexScore?: number;
    ratio?: "strip" | "1x1" | "2x1";
    onOpenDetail?: () => void;
}): HTMLDivElement {
    let curRatio: "strip" | "1x1" | "2x1" = opts.ratio || "2x1";
    const wrap = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "8px", width: "100%" }, role: "region", ariaLabel: "管家仿生 Bento 看板" });

    const render = () => {
        wrap.innerHTML = "";
        const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", gap: "8px", flexWrap: "wrap" } },
            lvxTag({ text: "Bento 自适应比例容器", tone: "brand", size: "sm" }),
            lvxSegmented({
                size: "sm",
                options: [
                    { value: "strip", label: "通栏 Strip" },
                    { value: "1x1", label: "1×1 方卡" },
                    { value: "2x1", label: "2×1 组合" },
                ],
                value: curRatio,
                onChange: v => { curRatio = v as any; render(); },
            }),
        );
        wrap.appendChild(head);

        if (curRatio === "strip") {
            wrap.appendChild(lvxH("div", {
                class: "lvx-ratio--strip",
                style: { background: "var(--lvx-surface)", border: "1px solid var(--lvx-border)" },
            },
                lvxChip({ text: `⏳ ${opts.eventTitle} · 剩 ${opts.daysLeft} 天`, tone: "energy", size: "sm" }),
                lvxH("span", { style: { fontSize: "12px" }, text: `🏮 ${opts.lunarText} (${opts.solarTerm})` }),
                lvxChip({ text: `🌤 ${opts.weatherText} · 指数 ${opts.lifeIndexScore ?? 96}`, tone: "success", size: "sm" }),
            ));
            return;
        }

        const root = lvxH("div", { class: curRatio === "1x1" ? "lvx-ratio--1x1" : "lvx-bento" });
        const heroCountdown = lvxCard({
            hero: true,
            interactive: true,
            onClick: opts.onOpenDetail,
            children: [
                lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "6px" } },
                    lvxChip({ text: "⏳ 证照/纪念日倒数", tone: "energy", size: "sm" }),
                    lvxTag({ text: opts.targetDate, size: "sm" }),
                ),
                lvxHeroNum({ value: `${opts.daysLeft} 天`, label: opts.eventTitle, tone: "energy" }),
            ],
        });
        root.appendChild(heroCountdown);

        if (curRatio === "2x1") {
            const rightStack = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "10px" } },
                lvxCard({
                    children: [
                        lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center" } },
                            lvxH("strong", { style: { fontSize: "13px" }, text: `🏮 ${opts.lunarText}` }),
                            lvxChip({ text: opts.solarTerm, tone: "brand", size: "sm" }),
                        ),
                        lvxH("div", { style: { fontSize: "12px", color: "var(--lvx-text-muted)", marginTop: "4px" }, text: "宜：复盘归档 · 断舍离对账 · 忌：散乱囤积" }),
                    ],
                }),
                lvxCard({
                    children: [
                        lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center" } },
                            lvxH("span", { style: { fontSize: "13px", fontWeight: "600" }, text: `🌤 ${opts.weatherText}` }),
                            lvxChip({ text: `家庭综合指数 ${opts.lifeIndexScore ?? 96} 分`, tone: "success", size: "sm" }),
                        ),
                    ],
                }),
            );
            root.appendChild(rightStack);
        }
        wrap.appendChild(root);
    };
    render();
    return wrap;
}

