/** 115. Ghostreader 行内伴读 AI 追问与高亮大纲树 GhostreaderPanel（拾遗最新演进） */
export function lvxGhostreaderPanel(opts: {
    selectedText?: string;
    activeAction?: "explain" | "arguments" | "critique" | "custom";
    answer?: string;
    evidence?: string[];
    outline?: Array<{ heading: string; items: Array<{ text: string; color: "yellow" | "red" | "blue" | "green" }> }>;
    onAction?: (action: string) => void;
    onInsertCallout?: () => void;
    onCopy?: () => void;
}): HTMLDivElement {
    let curAction = opts.activeAction || "explain";
    const actions: Array<{ id: string; label: string; icon: string }> = [
        { id: "explain", label: "用人话解释", icon: "✨" },
        { id: "arguments", label: "提炼核心论据", icon: "🔍" },
        { id: "critique", label: "批判性思考", icon: "⚡" },
        { id: "custom", label: "自由追问", icon: "💬" },
    ];
    const root = lvxH("div", { class: "lvx-ghostreader", role: "region", ariaLabel: "Ghostreader 伴读面板" });

    const top = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px" } },
            lvxChip({ text: "📖 Ghostreader 行内伴读", tone: "brand", size: "sm" }),
            lvxTag({ text: "实时 AI 语义透析", tone: "success", size: "sm" }),
        ),
        lvxH("div", { style: { display: "inline-flex", gap: "6px", flexWrap: "wrap" } },
            ...actions.map(a => lvxH("button", {
                type: "button",
                class: `lvx-pill-btn${a.id === curAction ? " is-active" : ""}`,
                style: {
                    padding: "4px 8px",
                    fontSize: "12px",
                    ...(a.id === curAction ? { borderColor: "var(--lvx-brand)", background: "var(--lvx-brand-tint)", color: "var(--lvx-brand)" } : {}),
                },
                onclick: () => { curAction = a.id as any; opts.onAction?.(a.id); },
            }, lvxH("span", { text: a.icon }), lvxH("span", { text: a.label }))),
        ),
    );
    root.appendChild(top);

    if (opts.selectedText) {
        root.appendChild(lvxH("div", {
            style: { padding: "8px 12px", borderRadius: "var(--lvx-r-md)", background: "var(--lvx-surface-sunken)", border: "1px solid var(--lvx-border)", fontSize: "12px", color: "var(--lvx-text-muted)" },
            text: `选中文本：“${opts.selectedText}”`,
        }));
    }

    const answerBox = lvxH("div", {
        style: { display: "flex", flexDirection: "column", gap: "6px", padding: "10px", borderRadius: "var(--lvx-r-md)", background: "var(--lvx-surface)", border: "1px solid var(--lvx-border-strong)", boxShadow: "var(--lvx-shadow-1)" },
    },
        lvxH("div", { style: { fontSize: "13px", lineHeight: "1.6" }, text: opts.answer || "✨ 用人话解释：把复杂的系统拓扑比作城市的地下排水网络，节点负责中转汇流，即使个别管道检修断开，全城生活用水依然零中断无感切换。" }),
        opts.evidence?.length ? lvxH("div", {
            style: { fontSize: "12px", color: "var(--lvx-brand)", background: "var(--lvx-brand-tint)", padding: "4px 8px", borderRadius: "6px" },
            text: `🔍 证据依据：${opts.evidence.join("；")}`,
        }) : null,
        lvxH("div", { style: { display: "flex", justifyContent: "flex-end", gap: "6px", paddingTop: "4px", flexWrap: "wrap", width: "100%" } },
            opts.onCopy ? lvxButton({ label: "📋 复制解析", sm: true, onClick: opts.onCopy }) : null,
            opts.onInsertCallout ? lvxButton({ label: "📌 插入思源 Callout", variant: "primary", sm: true, onClick: opts.onInsertCallout }) : null,
        ),
    );
    root.appendChild(answerBox);

    if (opts.outline?.length) {
        const outlineBox = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px", borderTop: "1px dashed var(--lvx-border)", paddingTop: "8px" } },
            lvxH("div", { style: { fontSize: "12px", fontWeight: "700", color: "var(--lvx-text-muted)" }, text: "📑 文档高亮章节大纲树 (Highlight Outline)" }),
        );
        const colorHexMap: Record<string, string> = { yellow: "var(--lvx-warn)", red: "var(--lvx-danger)", blue: "#3B82F6", green: "var(--lvx-success)" };
        for (const sec of opts.outline) {
            outlineBox.appendChild(lvxH("strong", { style: { fontSize: "12px", marginTop: "2px" }, text: sec.heading }));
            for (const it of sec.items) {
                outlineBox.appendChild(lvxH("div", {
                    style: { display: "flex", alignItems: "center", gap: "6px", paddingLeft: "12px", fontSize: "12px" },
                },
                    lvxH("span", { style: { width: "7px", height: "7px", borderRadius: "50%", background: colorHexMap[it.color] || "var(--lvx-warn)", flexShrink: "0" } }),
                    lvxH("span", { style: { minWidth: "0", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }, text: it.text }),
                ));
            }
        }
        root.appendChild(outlineBox);
    }

    return root;
}

/** 116. 错题消灭阶梯与试题变式特训面板 VariantDrillStudio（考试最新演进） */
export function lvxVariantDrillStudio(opts: {
    seedStem: string;
    seedAnswer: string;
    ladderStage?: "to_conquer" | "strengthening" | "mastered";
    streakCorrect?: number;
    variants?: Array<{ id: string; label: string; desc: string }>;
    onDrillAnswer?: (answer: string) => void;
    onPromoteLadder?: () => void;
}): HTMLDivElement {
    const stage = opts.ladderStage || "strengthening";
    const stagesMeta = {
        to_conquer: { label: "🔴 待攻克 (Level 1)", desc: "近期做错，核心失分薄弱点", tone: "danger" as LvxTone },
        strengthening: { label: "🟡 强化中 (Level 2)", desc: "独立答对 1 次，需再连对出库", tone: "energy" as LvxTone },
        mastered: { label: "🟢 已掌握 (Level 3)", desc: "连续答对出库，彻底掌握", tone: "success" as LvxTone },
    }[stage];

    const root = lvxH("div", { class: "lvx-drill", role: "region", ariaLabel: "错题变式特训" });

    const top = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px" } },
            lvxChip({ text: stagesMeta.label, tone: stagesMeta.tone, size: "sm" }),
            lvxTag({ text: `连对数 ${opts.streakCorrect ?? 1}/2`, tone: "brand", size: "sm" }),
        ),
        lvxH("span", { style: { fontSize: "12px", color: "var(--lvx-text-muted)" }, text: stagesMeta.desc }),
    );
    root.appendChild(top);

    const seedBox = lvxH("div", {
        style: { padding: "8px 10px", borderRadius: "8px", background: "var(--lvx-surface-sunken)", border: "1px solid var(--lvx-border)", fontSize: "13px" },
    },
        lvxH("div", { style: { fontSize: "11px", fontWeight: "700", color: "var(--lvx-text-muted)", marginBottom: "4px" }, text: "🌱 错题原题种子" }),
        lvxH("strong", { text: opts.seedStem }),
        lvxH("div", { style: { fontSize: "12px", color: "var(--lvx-success)", marginTop: "4px" }, text: `标准答案：${opts.seedAnswer}` }),
    );
    root.appendChild(seedBox);

    const variantBox = lvxH("div", {
        style: { display: "flex", flexDirection: "column", gap: "6px", padding: "10px", borderRadius: "10px", background: "var(--lvx-surface)", border: "1px solid var(--lvx-border-strong)" },
    },
        lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center" } },
            lvxH("strong", { style: { fontSize: "13px" }, text: "⚡ AI 生成变式题（概念翻转逆向题）" }),
            lvxChip({ text: "难度自适应系数 1.25", tone: "brand", size: "sm" }),
        ),
        lvxH("div", { style: { fontSize: "13px", lineHeight: "1.5" }, text: "【变式】设方阵 A 的每一列都是非零向量，若 A 的行列式 det(A) = 0，则下列结论必然正确的是？" }),
        lvxH("div", { style: { display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "6px" } },
            ...["A. A 的列向量组线性相关", "B. A 的行向量组线性无关", "C. 矩阵 A 可逆", "D. 矩阵秩 rank(A) = n"].map(opt => lvxH("button", {
                type: "button",
                class: "lvx-list-item lvx-list-item--interactive",
                style: { padding: "8px 10px", fontSize: "12px" },
                onclick: () => opts.onDrillAnswer?.(opt.slice(0, 1)),
            }, lvxH("span", { text: opt }))),
        ),
    );
    root.appendChild(variantBox);

    if (opts.onPromoteLadder) {
        root.appendChild(lvxH("div", { style: { display: "flex", justifyContent: "flex-end", width: "100%" } },
            lvxButton({ label: "⬆ 晋升下一阶梯", sm: true, variant: "primary", onClick: opts.onPromoteLadder }),
        ));
    }

    return root;
}

/** 117. 易歪歪对标双核分类树与短语瀑布流面板 DualCoreSidebar（常用最新演进） */
export function lvxDualCoreSidebar(opts: {
    categories: Array<{ id: string; name: string; count: number; icon: string }>;
    phrases: Array<{ id: string; title: string; category: string; snippet: string; vars?: string[] }>;
    activeCat?: string;
    onSelectCat?: (id: string) => void;
    onInsert?: (phraseId: string) => void;
}): HTMLDivElement {
    let curCat = opts.activeCat || opts.categories[0]?.id || "biz";
    const root = lvxH("div", { class: "lvx-dualcore", role: "region", ariaLabel: "双核短语面板" });

    const searchBox = lvxInput({ placeholder: "🔍 搜索话术正文/变量/标签...", size: "sm" });
    searchBox.style.flex = "1";
    searchBox.style.minWidth = "0";
    searchBox.style.width = "100%";
    const head = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px", width: "100%" } },
        lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%" } },
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "6px", flexWrap: "wrap" } },
                lvxChip({ text: "📋 双核话术侧栏", tone: "brand", size: "sm" }),
                lvxTag({ text: "秒级上屏", tone: "success", size: "sm" }),
            ),
        ),
        searchBox,
    );
    root.appendChild(head);

    const layout = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "8px", width: "100%" } });

    // 分类导航条（支持手机端横向平滑滑动，杜绝双栏挤压断裂）
    const tree = lvxH("div", {
        style: { display: "flex", gap: "6px", overflowX: "auto", scrollbarWidth: "none", flexWrap: "nowrap", padding: "4px", borderRadius: "var(--lvx-r-md)", background: "var(--lvx-surface-sunken)", border: "1px solid var(--lvx-border)", width: "100%" },
    });
    for (const c of opts.categories) {
        const isAct = c.id === curCat;
        const item = lvxH("button", {
            type: "button",
            class: "lvx-pill-btn",
            style: {
                justifyContent: "space-between", padding: "5px 8px", fontSize: "12px",
                background: isAct ? "var(--lvx-brand)" : "transparent",
                color: isAct ? "var(--lvx-on-brand)" : "var(--lvx-text)",
                borderColor: isAct ? "var(--lvx-brand)" : "transparent",
                flexShrink: "0", whiteSpace: "nowrap",
            },
            onclick: () => { curCat = c.id; opts.onSelectCat?.(c.id); },
        },
            lvxH("span", { text: `${c.icon} ${c.name}` }),
            lvxTag({ text: String(c.count), size: "sm" }),
        );
        tree.appendChild(item);
    }
    layout.appendChild(tree);

    const list = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px" } });
    for (const p of opts.phrases) {
        const card = lvxH("div", {
            class: "lvx-list-item",
            style: { display: "flex", flexDirection: "column", gap: "4px", padding: "8px 10px", background: "var(--lvx-surface)" },
        },
            lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", gap: "8px", width: "100%" } },
                lvxH("strong", { style: { fontSize: "13px", flex: "1 1 auto", minWidth: "0", wordBreak: "break-word" }, text: p.title }),
                lvxButton({ label: "⚡ 上屏", variant: "primary", sm: true, onClick: () => opts.onInsert?.(p.id) }),
            ),
            lvxH("span", { style: { fontSize: "12px", color: "var(--lvx-text-muted)" }, text: p.snippet }),
            p.vars?.length ? lvxH("div", { style: { display: "inline-flex", gap: "4px", flexWrap: "wrap", marginTop: "2px" } },
                ...p.vars.map(v => lvxTag({ text: `{{${v}}}`, tone: "energy", size: "sm" })),
            ) : null,
        );
        list.appendChild(card);
    }
    layout.appendChild(list);
    root.appendChild(layout);

    return root;
}

/** 118. 闪卡交互式即时作答与三阶进度导览 InteractiveQuizCard（闪卡最新演进） */
export function lvxInteractiveQuizCard(opts: {
    stem: string;
    options: string[];
    breadcrumb?: string;
    progress?: { newCount: number; learnCount: number; reviewCount: number };
    memoCallout?: string;
    onAnswer?: (index: number) => void;
}): HTMLDivElement {
    let selectedIdx: number | null = null;
    const root = lvxH("div", { class: "lvx-quizcard", role: "region", ariaLabel: "闪卡交互答题卡" });

    const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "6px" } },
        lvxH("span", { style: { fontSize: "12px", color: "var(--lvx-text-muted)", flex: "1 1 160px", minWidth: "0", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }, text: `📚 ${opts.breadcrumb || "分布式系统 · 共识算法"}` }),
        opts.progress ? lvxH("div", { style: { display: "inline-flex", gap: "4px", flexShrink: "0" } },
            lvxChip({ text: `新 ${opts.progress.newCount}`, tone: "brand", size: "sm" }),
            lvxChip({ text: `学 ${opts.progress.learnCount}`, tone: "energy", size: "sm" }),
            lvxChip({ text: `到期 ${opts.progress.reviewCount}`, tone: "success", size: "sm" }),
        ) : null,
    );
    root.appendChild(head);

    const questionBox = lvxH("div", {
        style: { padding: "12px", borderRadius: "var(--lvx-r-md)", background: "var(--lvx-surface-sunken)", border: "1px solid var(--lvx-border)", fontSize: "14px", fontWeight: "650", lineHeight: "1.5" },
        text: opts.stem,
    });
    root.appendChild(questionBox);

    const optList = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px" } });
    opts.options.forEach((opt, idx) => {
        const isSel = selectedIdx === idx;
        const btn = lvxH("button", {
            type: "button",
            class: "lvx-list-item lvx-list-item--interactive",
            style: {
                padding: "8px 12px", fontSize: "13px", justifyContent: "space-between",
                borderColor: isSel ? "var(--lvx-brand)" : "var(--lvx-border)",
                background: isSel ? "var(--lvx-brand-tint)" : "var(--lvx-surface)",
            },
            onclick: () => {
                selectedIdx = idx;
                opts.onAnswer?.(idx);
                Array.from(optList.children).forEach((child, cIdx) => {
                    const el = child as HTMLElement;
                    const act = cIdx === idx;
                    el.style.borderColor = act ? "var(--lvx-brand)" : "var(--lvx-border)";
                    el.style.background = act ? "var(--lvx-brand-tint)" : "var(--lvx-surface)";
                    el.setAttribute("aria-pressed", act ? "true" : "false");
                });
            },
        },
            lvxH("span", { style: { flex: "1", minWidth: "0", wordBreak: "break-word", lineHeight: "1.45" }, text: opt }),
            lvxH("span", { style: { flexShrink: "0", display: "inline-flex" } }, lvxKbd(String(idx + 1))),
        );
        optList.appendChild(btn);
    });
    root.appendChild(optList);

    if (opts.memoCallout) {
        const memo = lvxH("div", {
            style: { display: "flex", alignItems: "flex-start", gap: "8px", padding: "8px 10px", borderRadius: "8px", background: "color-mix(in srgb, var(--lvx-energy) 12%, transparent)", border: "1px solid rgba(245,158,11,0.25)", fontSize: "12px", color: "var(--lvx-energy-strong)" },
        },
            lvxH("span", { text: "💡" }),
            lvxH("div", { text: opts.memoCallout }),
        );
        root.appendChild(memo);
    }

    return root;
}


/** 119. 人脉五级生命周期漏斗与人脉池深度卡 LifecycleFunnelCard（人脉核心看板） */
export function lvxLifecycleFunnelCard(opts: {
    stages?: Array<{ id: string; name: string; count: number; pct: number; color?: string }>;
    totalContacts?: number;
    dormantWarning?: number;
    onStageClick?: (stageId: string) => void;
}): HTMLDivElement {
    const stages = opts.stages || [
        { id: "acquaintance", name: "初识结缘", count: 48, pct: 36, color: "var(--lvx-brand-soft)" },
        { id: "familiar", name: "日常熟络", count: 32, pct: 24, color: "var(--lvx-brand)" },
        { id: "trusted", name: "深度信任", count: 26, pct: 20, color: "#3b82f6" },
        { id: "core", name: "核心挚友", count: 18, pct: 14, color: "var(--lvx-success)" },
        { id: "dormant", name: "沉睡待唤醒", count: 8, pct: 6, color: "var(--lvx-energy)" },
    ];
    const root = lvxH("div", { class: "lvx-funnel", role: "region", ariaLabel: "人脉生命周期漏斗" });
    const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px" } },
            lvxChip({ text: "👥 人脉五阶生命周期漏斗", tone: "brand", size: "sm" }),
            lvxTag({ text: `总联络池 ${opts.totalContacts || 132} 人`, size: "sm" }),
        ),
        opts.dormantWarning ? lvxTag({ text: `⚠️ ${opts.dormantWarning} 人超过 30 天未联络`, tone: "energy", size: "sm" }) : null,
    );
    root.appendChild(head);

    const funnelBox = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "6px" } });
    for (const st of stages) {
        const bar = lvxH("div", {
            class: "lvx-list-item lvx-list-item--interactive",
            style: { padding: "8px 12px", fontSize: "12px", justifyContent: "space-between", cursor: "pointer" },
            role: "button",
            tabIndex: 0,
            onclick: () => opts.onStageClick?.(st.id),
            onkeydown: (ev: KeyboardEvent) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); opts.onStageClick?.(st.id); } },
        },
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px", minWidth: "100px" } },
                lvxH("span", { style: { width: "8px", height: "8px", borderRadius: "50%", background: st.color || "var(--lvx-brand)", flexShrink: "0" } }),
                lvxH("strong", { text: st.name }),
            ),
            lvxH("div", { style: { flex: "1", margin: "0 12px", height: "8px", borderRadius: "4px", background: "var(--lvx-surface-sunken)", overflow: "hidden" } },
                lvxH("div", { style: { width: `${st.pct}%`, height: "100%", borderRadius: "4px", background: st.color || "var(--lvx-brand)" } }),
            ),
            lvxH("span", { style: { fontVariantNumeric: "tabular-nums", fontWeight: "600", color: "var(--lvx-text-muted)" }, text: `${st.count} 人 (${st.pct}%)` }),
        );
        funnelBox.appendChild(bar);
    }
    root.appendChild(funnelBox);
    return root;
}

/** 120. 拾遗长文渐进切片与阅读进度看板 DocSlicingCard（对标 Readwise Reader） */
export function lvxDocSlicingCard(opts: {
    title: string;
    totalWords: number;
    slices: Array<{ id: string; title: string; words: number; eta: string; status: "done" | "reading" | "pending" }>;
    onJumpSlice?: (sliceId: string) => void;
}): HTMLDivElement {
    const root = lvxH("div", { class: "lvx-slicing", role: "region", ariaLabel: "长文渐进切片阅读卡" });
    const head = lvxH("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "8px" } },
        lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px" } },
            lvxChip({ text: "📖 长文切片阅读工作台", tone: "brand", size: "sm" }),
            lvxTag({ text: `共 ${opts.slices.length} 个切片 · ${(opts.totalWords/1000).toFixed(1)}k 字`, size: "sm" }),
        ),
        lvxButton({ label: "⚡ 直达当前阅读切片", sm: true, variant: "primary", onClick: () => opts.onJumpSlice?.(opts.slices.find(s => s.status === "reading")?.id || "") }),
    );
    root.appendChild(head);

    const sliceList = lvxH("div", { style: { display: "flex", flexDirection: "column", gap: "5px" } });
    opts.slices.forEach((s, idx) => {
        const isReading = s.status === "reading";
        const isDone = s.status === "done";
        const row = lvxH("div", {
            class: "lvx-list-item lvx-list-item--interactive",
                    role: "button",
                    tabIndex: 0,
            style: {
                padding: "8px 12px", fontSize: "12px", justifyContent: "space-between", cursor: "pointer",
                borderColor: isReading ? "var(--lvx-brand)" : "var(--lvx-border)",
                background: isReading ? "var(--lvx-brand-tint)" : isDone ? "var(--lvx-surface-sunken)" : "var(--lvx-surface)",
            },
            onclick: () => opts.onJumpSlice?.(s.id),
            onkeydown: (ev: KeyboardEvent) => {
                if (ev.isComposing || ev.keyCode === 229) return;
                if (ev.key === "Enter" || ev.key === " ") {
                    ev.preventDefault();
                    opts.onJumpSlice?.(s.id);
                }
            },
        },
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px", minWidth: "0" } },
                lvxTag({ text: `#${idx + 1}`, size: "sm", tone: isReading ? "brand" : isDone ? "success" : "neutral" }),
                lvxH("strong", { style: { minWidth: "0", textOverflow: "ellipsis", overflow: "hidden", whiteSpace: "nowrap" }, text: s.title }),
            ),
            lvxH("div", { style: { display: "inline-flex", alignItems: "center", gap: "8px", flexShrink: "0" } },
                lvxH("span", { style: { fontSize: "11px", color: "var(--lvx-text-muted)" }, text: `约 ${s.eta}` }),
                isDone ? lvxTag({ text: "✓ 已读完", size: "sm", tone: "success" })
                    : isReading ? lvxTag({ text: "⏳ 正在读", size: "sm", tone: "brand" })
                    : lvxTag({ text: "待阅读", size: "sm", tone: "neutral" }),
            ),
        );
        sliceList.appendChild(row);
    });
    root.appendChild(sliceList);
    return root;
}

